// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Felsefe tarihi: İlk Çağ ve Orta Çağ (orta).
const ozSocialscience11Orta = <(String, String, List<String>, String)>[
  ('Aşağıdakilerden hangisi mitolojik anlatım ile ilk felsefi açıklama arasındaki temel farkı en iyi belirtir?', 'Mitler olayları tanrıların iradesiyle, felsefe ise doğadaki nedenlerle ve akıl yürütmeyle açıklamaya çalışır', ['Mitler yazıya geçirilmemiştir, felsefe ise yalnız şiir biçiminde anlatılmış ve gizli tutulmuştur', 'Mitler yalnız insanı, felsefe ise yalnız doğayı konu edinir ve ikisi hiç örtüşmez', 'Mitler her zaman eleştiriye açıktır, felsefi görüşler ise kesinlikle tartışılmaz sayılır'], 'Felsefeyi başlatan tutum, olayların açıklamasını tanrısal müdahalede değil, doğanın kendi içindeki nedenlerde aramaktır. Mitler ise anlatıya dayanır ve sınanmaz.'),
  ('Pythagorasçı topluluğun "mathematikoi" olarak anılan üyeleri kimlerdir?', 'Öğretinin bilimsel ve matematiksel yönünü öğrenen ileri düzey iç halka', ['Yalnızca kuralları ve yasakları ezberleyen, öğretinin gerekçelerini öğrenmeyen yeni üyeler', 'Toplulukla uzak ülkeler arasındaki ticareti yürüten ve gelirini paylaşan tüccarlar', 'Topluluğun siyasi yönetimini ve ordusunu üstlenen, kent yönetimine katılan üyeler'], 'Topluluk "akusmatikoi" (dinleyiciler) ve "mathematikoi" olmak üzere ikiye ayrılırdı. Mathematikoi öğretinin gerekçelerini kavrayan, daha ileri düzeydeki üyelerdi.'),
  ('Pythagorasçı Philolaos\'un astronomi anlayışının özgün yanı nedir?', 'Dünyayı merkeze koymayıp onu merkezî bir ateşin çevresinde dönen gök cisimlerinden biri saydı', ['Güneşin Dünya\'nın çevresinde döndüğünü uzun gözlemlerle kanıtlayıp ilk kez ispatlaması', 'Yıldızların kristal bir küre yüzeyine çivilenmiş olduğunu ileri sürmesi ve küreyi sabit saymasıdır', 'Ayın kendi ışığını yaydığını, Güneşin ise yalnızca bir yansıma olduğunu savunması'], 'Philolaos\'a atfedilen sistemde Dünya, Ay, Güneş ve gezegenler merkezî bir ateşin çevresinde döner. Dünya\'nın evrenin merkezi olmadığı fikri bakımından dikkat çekicidir.'),
  ('Herakleitos\'un arkhe olarak ateşi seçmesinin gerekçesi aşağıdakilerden hangisine en yakındır?', 'Ateşin sürekli hareketli olması ve her şeye dönüşüp yine kendine dönmesi, evrenin sürekli oluşuna uygun düşer', ['Ateşin bütün elementlerin en ağırı olması ve her şeyin onun yoğunlaşmasıyla katılaşması', 'Ateşin suyu tümüyle yok edip yeri sabit ve değişmez bir evren bırakması', 'Ateşin yalnız Güneş\'te bulunması ve yeryüzündeki her şeyden ayrı olması'], 'Ateş durmadan değişen ve her şeyi dönüştüren bir şeydir. Bu özellik Herakleitos\'un her şeyin akışta olduğu görüşüne doğal bir simge sağlar.'),
  ('Parmenides varlığın doğmuş ya da yok olabilir olamayacağını hangi gerekçeyle savunur?', 'Yokluktan varlık çıkamaz, varlık da yokluğa dönüşemez', ['Doğanın yalnız dört öğeden oluşması, bu yüzden değişmeyen bir öğenin bulunması', 'Zamanın dairesel işlemesi nedeniyle', 'Duyuların bunu kanıtlaması nedeniyle'], 'Parmenides\'e göre yok olan düşünülemez ve söylenemez. Bu nedenle varlık yokluktan oluşamaz ve yokluğa gidemez; o ezelî ve değişmezdir.'),
  ('Elealı Zenon\'un "dikotomi" paradoksuna göre bir uzaklığı kat etmek neden olanaksızdır?', 'Önce yarısına, ondan önce yarısının yarısına ulaşmak gibi sonsuz sayıda aşamayı tamamlamak gerekir', ['Rakibin her zaman daha hızlı davranmak zorunda olması ve yarışın bu yüzden kazanılmaması', 'Zeminin sürekli kendi kendine hareket etmesi, bu yüzden mesafenin hiç sabit kalmaması', 'Zamanın tamamen durması ve hiçbir hareketin başlayamaması nedeniyle'], 'Her uzaklık sonsuz kez yarıya bölünebildiğinden hareketin başlaması bile olanaksız görünür. Zenon bununla çokluk ve hareketi varsayanların çelişkiye düştüğünü göstermek ister.'),
  ('Demokritos\'a göre tat, renk ve sıcaklık gibi duyusal niteliklerin gerçek durumu nedir?', 'Gerçekte yalnız atomlar ve boşluk vardır; bu nitelikler "gelenekle" (nomos) var olan algılardır', ['Atomların kendi öz nitelikleridir ve atomlar rengi, tadı ve sıcaklığı taşırlar', 'Tanrıların insanlara armağan ettiği, doğuştan bilinen ve değişmez nitelikleridir', 'Boşluğun ürettiği ve yalnız belirli zamanlarda görünen yansımalardır'], 'Demokritos\'a göre renk, tat gibi nitelikler algılayana göre değişir. Gerçekte var olan yalnızca atomlar ve boşluktur.'),
  ('Demokritos\'un evren anlayışı nasıl nitelendirilebilir?', 'Her olay zorunlu bir nedene bağlıdır; rastlantı bilgisizlikten doğan bir sözdür', ['Evren rastlantıyla işler ve nedensellik diye bir şey yoktur, olaylar tümüyle serbest gerçekleşir', 'Evrenin gidişini tanrılar sürekli değiştirir ve müdahale ederek düzeni yeniden kurar', 'Evren her an yeniden yaratılır ve önceki durumundan hiçbir iz taşımaz'], 'Atomcular her olayı atomların çarpışma ve zorunluluğu ile açıkladı. Rastlantı, nedenin bilinmemesinden doğan bir görüntü sayıldı; bu determinist bir bakıştır.'),
  ('Doğa filozoflarından biri "Her şey sudandır" demişken bir başkası "Her şey sınırsızdan çıkar" diyor. İki görüşün ortak yanı aşağıdakilerden hangisidir?', 'Evrenin çokluğunu tek bir ilkeye indirerek ve doğa içinden açıklamaya çalışmaları', ['İkisinin de ilkeyi duyularla göremeyeceğini ve ona yalnızca vahiyle ulaşılacağını savunmaları', 'İkisinin de ilkeyi bir tanrı saymaları ve evreni onun iradesiyle açıklamaları', 'İkisinin de evrenin hep durağan ve değişmez olduğunu savunmaları'], 'Her iki görüşte de evren tek bir doğal ilkeden türetilir ve açıklama mit yerine doğadan aranır. Aralarındaki fark, ilkenin belirli bir madde mi yoksa belirsiz mi olduğudur.'),
  ('Platon "Gorgias" diyaloğunda Sokrates\'in karşısına Kallikles\'i çıkarır. Kallikles hangi görüşü savunur?', 'Doğa gereği güçlünün zayıf üzerinde üstün olması haktır', ['Adaletin bilgiyle aynı şey olduğu ve herkesin eşit olması gerektiği', 'Mutluluğun yalnızca erdemden ibaret olduğu ve erdemli kişinin her koşulda mutlu olduğu', 'Tüm yasaların doğrudan tanrılardan geldiği ve insanlar tarafından değiştirilemeyeceği'], 'Kallikles yasaların zayıfların güçlüyü zapt etmek için koyduğunu ve doğal adaletin güçlünün üstünlüğü olduğunu savunur. Sokrates buna erdemli yaşamın daha iyi olduğu yanıtını verir.'),
  ('Sokrates yargılanma sırasında kendisine verilen "daimonion"u nasıl tanımlar?', 'Onu belli şeyleri yapmaktan alıkoyan içsel bir ilahi ses', ['Kendisine gelecekteki savaşları önceden bildiren bir tanrıça sesi', 'Sürekli kendisini izleyen bir koruyucu asker', 'Atina yasalarının görünmeyen yargıcı'], 'Platon\'un "Savunma"sında Sokrates, çocukluğundan beri onu yanlış bir şeyden alıkoyan, ama hiçbir zaman bir şeye yöneltmeyen ilahi bir ses duyduğunu anlatır.'),
  ('Delphoi kâhini Sokrates\'ten daha bilge kimse olmadığını söylemiştir. Sokrates bu kehaneti nasıl değerlendirmiştir?', 'Bilge sayılanları sorgulayıp kendi bilgisizliğinin bilincinde olmasının onu farklı kıldığı sonucuna varmıştır', ['Kehaneti kendisini devlet başkanı yapmak için bir dayanak olarak kullanıp siyasete atılmıştır', 'Kehaneti reddetmiş, Delphoi\'ye hiç gitmemiş ve yalnız kendi aklına güvenmiştir', 'Kendisini bilgelerin en yücesi ilan etmiş ve herkesi öğrencisi olmaya çağırmıştır'], 'Sokrates kehaneti sınamak için bilge sayılanları sorguladı. Onların bilmediklerini bildiklerini sanmasına karşılık kendi bilgisizliğinin bilincinde olmasının bilgeliğinin kaynağı olduğunu anladı.'),
  ('Kinik filozof Diogenes\'in Büyük İskender\'e "Güneşimi kesme" demesi neyi yansıtır?', 'Gücün ve servetin önemsenmediğini, bağımsızlığın değer sayıldığını', ['İskender\'e duyduğu büyük hayranlık ve onun ordusuna katılma isteği', 'Güneşe tapınması ve güneşin tanrısal bir varlık olduğuna inanması', 'Askerlik hizmetini reddetmesi ve savaşlara karşı çıkması'], 'Diogenes İskender\'in her isteğini sormasına karşılık yalnızca güneşten çekilmesini istedi. Kinikler ihtiyaçlardan arınma ve kimseye bağımlı olmamayı önemserdi.'),
  ('Kinik okuluna adını veren "kynikos" sözcüğü ne anlama gelir?', 'Köpek gibi', ['Fıçıcı, yani fıçıda yaşayanlar', 'Yoksul, yani mal sahibi olmayanlar', 'Gezgin, yani kentten kente dolaşan öğretmenler'], 'Kinikler toplumsal geleneklerden bağımsız, köpekçe yaşam sürdükleri için bu adla anıldı. Sözcük Yunanca köpek anlamındaki kyon ile ilişkilidir.'),
  ('Kinik düşüncede erdemli yaşamın temel koşulu olarak görülen "autarkeia" nedir?', 'Kendine yeterlilik, dış şeylere bağımlı olmama', ['Siyasal iktidarı ele geçirerek toplumu yönetmek ve düzenlemek', 'Mal biriktirerek güvence sağlama ve gelecek kaygısını gidermek', 'Tanrılara bağlılıkla yaşayıp her işi kehanetlere sormak'], 'Kinikler mutluluğun gereksinimleri azaltıp kendine yeterli olmaktan geçtiğini savundu. Bu yüzden servet, ün ve toplumsal gelenek onlar için değersizdi.'),
  ('Platon\'un neredeyse bütün eserlerini diyalog biçiminde yazmasının felsefi yönden anlamı nedir?', 'Gerçeğin tek bir sesle dayatılmak yerine soru-cevapla sınanarak aranması gerektiği görüşüne uygun düşer', ['Yazarın kendi görüşünü hiç bildirmemesi gerektiğine ilişkin yazılı bir kural bulunması', 'Antik Atina\'da bütün yazarların diyalog biçiminde yazmak zorunda olması', 'Diyalogların yalnız tiyatro sahnesinde oynanmak üzere yazılması ve okunmaması'], 'Diyalog biçimi Sokrates\'in sorgulayıcı yöntemine yakındır ve düşünceyi dogma olarak değil, ortak bir araştırma olarak sunar.'),
  ('Platon "Yedinci Mektup"ta Syrakusa ziyaretleriyle ne amaçlamıştır?', 'Filozofun yönetiminde ideal bir devleti uygulamayı denemek', ['Ticaretle büyük servet kazanıp Akademia\'yı finanse etmeyi', 'Syrakusa için bir ordu yetiştirip kenti Atina\'ya bağlamayı', 'Akademia için Sicilya\'da geniş arazi satın alıp tarım yapmayı'], 'Platon Syrakusa\'da genç yönetici Dionysios\'u filozof yönetici yetiştirmeyi umdu. Girişim siyasal çalkantılar nedeniyle başarısız oldu.'),
  ('Platon\'un "bölünmüş çizgi" benzetmesinde bilgi derecelerinin en altında yer alan "eikasia" neyi ifade eder?', 'Gölge ve yansımalara dayalı tahmin', ['Matematiksel çıkarım ve varsayımlardan türetme yöntemi', 'İdeaların doğrudan kavranması', 'Duyusal nesnelere inanç'], 'Çizgi önce görünür ve düşünülür alanlara bölünür. En alttaki eikasia, gölge ve yansımalar gibi görüntüleri hakikat sanmaktır; sonra inanç (pistis), düşünce (dianoia) ve akıl (noesis) gelir.'),
  ('Platon, ideal devletin yurttaşlarının sınıf düzenini kabul etmesi için hangi kurguyu önerir?', '"Soylu yalan": herkes toprağın çocuğudur, ruhlarına altın, gümüş ya da tunç karışmıştır', ['Her yurttaşın kendi sınıfını oyla seçmesi', 'Sınıfların her yıl çekilen kurayla belirlenmesi', 'Sınıfların yaşa göre otomatik değişmesi'], 'Platon yurttaşlara toprağın çocukları ve kardeşler olduklarının anlatılmasını, ruhlarındaki metale göre görev almalarının doğal olduğunu söylemeyi önerir. Buna soylu yalan denir.'),
  ('Platon "Devlet"te kadınların yönetim ve savunma görevlerine katılması konusunda nasıl bir görüş savunur?', 'Yeterli yeteneği olan kadınlar erkeklerle aynı eğitimi alıp koruyucu olabilir', ['Kadınlar yalnızca evde çocuk yetiştirmelidir', 'Kadınlar yalnızca üretici sınıfta çalışabilir', 'Kadınlar devlet işlerinden tümüyle dışlanmalıdır'], 'Platon doğa bakımından kadın ve erkek arasında görev ayrımı gerektiren köklü fark görmez ve yetenekli kadınları koruyucu sınıfa dahil eder. Bu, çağının koşullarında sıra dışıdır.'),
  ('Platon\'un son büyük eseri "Yasalar"da ideal devlete göre nasıl bir devlet önerilir?', 'Yasanın egemen olduğu, özel mülkiyetin kısmen kabul edildiği ikinci en iyi devlet', ['Hiçbir yasanın bulunmadığı bir devlet', 'Yalnızca askerlerin yönettiği bir devlet', 'Bütün mülkiyetin tek kişiye ait olduğu bir devlet'], 'Platon "Yasalar"da ideal filozof krallığı uygulanamaz bulup yasanın üstünlüğüne dayanan, kısmen mülkiyete izin veren ikinci en iyi devleti anlatır.'),
  ('"Phaidros"ta Platon, yazının bilgiye zarar verdiğini hangi öykü aracılığıyla ileri sürer?', 'Mısır tanrısı Theuth\'un yazıyı kral Thamus\'a sunması', ['Prometheus\'un ateşi çalması ve insanlara teknik bilgiyi armağan etmesi', 'Sisyphos\'un kayası', 'Orpheus\'un yeraltına inmesi'], 'Kral Thamus yazının insanlara unutkanlık getireceğini, gerçek bilgi yerine yalnızca bilgi görüntüsü vereceğini söyler. Platon bu yüzden konuşmayı yazıdan üstün tutar.'),
  ('Platon\'un "Phaidon" diyaloğundaki "zıtlardan zıtların doğması" argümanı neyi kanıtlamaya çalışır?', 'Ruhun ölümsüzlüğünü; yaşayan ölüden, ölü de yaşayandan doğduğu için ruhun yeniden doğuşunu', ['Evrenin bir başlangıcı olduğunu', 'Hazzın bir kötülük olduğunu', 'Yönetimin demokrasi olması gerektiğini'], 'Uyanıklıktan uykunun, uykudan uyanıklığın doğması gibi yaşamdan ölüm, ölümden yaşam doğar. Bu yüzden ölenlerin ruhlarının var olmayı sürdürdüğü ve yeniden doğduğu sonucuna varılır.'),
  ('Platon felsefesinde duyulur nesnelerin ideaya "katılması" anlamına gelen terim hangisidir?', 'Metheksis', ['Mimesis (taklit) kavramı', 'Katharsis', 'Anamnesis'], 'Platon bireysel nesnelerin ideaya katılarak niteliklerini kazandığını söyler. İdea ile nesne arasındaki bu ilişki hem katılım hem taklit olarak açıklanır.'),
  ('Platon\'un "Ion" diyaloğunda şairlerin yaratıcılığı nasıl açıklanır?', 'Bilgiyle değil tanrısal esinle, mıknatıs halkalarının zinciri gibi', ['Uzun bir eğitimin ürünü olarak', 'Doğa yasalarının bilinmesiyle', 'Toplumsal sözleşmenin sonucu olarak'], 'Sokrates, şairlerin ve ozanların bir sanat bilgisine değil tanrının verdiği ilhama dayandığını, esinin mıknatısın halkaları birbirine tutturması gibi aktarıldığını söyler.'),
  ('Platon\'a göre matematik bilgisi, bölünmüş çizgide "dianoia" basamağına girer. Bu basamağın özelliği nedir?', 'Varsayımlardan yola çıkıp görünür şekilleri yardımcı olarak kullanması', ['İdeaları doğrudan ve aracısız kavraması', 'Yalnızca gölgelerle uğraşması', 'Yalnızca tanrısal esine dayanması'], 'Matematikçiler varsayımları sorgulamadan kabul edip şekiller kullanır. Bu yüzden dianoia, ideaları doğrudan kavrayan noesis\'ten aşağıda kalır.'),
  ('Aristoteles\'in "ikinci töz" kavramı neyi anlatır?', 'Tek tek varlıkların ait olduğu tür ve cins', ['Bir şeyin rastlantısal niteliklerinin tamamı', 'Tanrı ile evren arasındaki bağ', 'Ruhun beden dışındaki varlığı'], 'Birinci töz belirli tek tek varlıklardır (bu insan, bu at). İkinci töz ise bunların ait olduğu tür ve cinslerdir (insan, hayvan).'),
  ('Aristoteles\'in Platon\'dan farklı olarak "ilk felsefe"de asıl incelediği şey nedir?', '"Varlık olarak varlık" ve onun ilk ilkeleri', ['Yalnızca insanın ahlaki davranışları ve toplumsal ilişkileri', 'Yıldızların hareketleri', 'Devletlerin yönetim şekli'], 'Aristoteles ilk felsefeyi, belirli bir alanla sınırlı olmayan, varlığı varlık olması bakımından ve onun ilke ve nedenlerini araştıran bilim olarak tanımlar.'),
  ('Aristoteles\'e göre ilk hareket ettirici evreni hangi biçimde hareket ettirir?', 'Sevilen ve arzulanan bir şey gibi, kendisi hareket etmeden', ['Doğrudan itme gücüyle, yani maddesel bir temas yoluyla', 'Ağırlığıyla aşağıya çekerek', 'Evrene sürekli ateş vererek'], 'Aristoteles\'in Tanrısı sevilen şey gibi hareket ettirir; kendisi saf düşünce ve değişmeyendir. Evren ona yönelerek hareket eder.'),
  ('Aristoteles\'in akıl için kullandığı "yazılmamış tablet" benzetmesi neyi anlatır?', 'Akıl doğuştan bilgi taşımaz, düşünceler deneyimle yazılır', ['Aklın doğuştan tüm bilgiyi taşıdığını ve deneyimin yalnız ona hatırlattığını', 'Bilginin yazıyla öğretilemeyeceğini', 'Bilgiyi yalnızca tanrıların yazabileceğini'], 'Aristoteles, akıl bilmeden önce hiçbir şeyi bilfiil düşünmüş olmaz; ancak düşünme yeteneğine sahiptir diye anlatır. Bu, deneyime dayanan bilgi anlayışının köklerindendir.'),
  ('Aristoteles\'in "akrasia" kavramı neyi anlatır?', 'Doğruyu bildiği hâlde irade zayıflığıyla buna aykırı davranmayı', ['Bütün arzulardan kurtulmayı', 'Tanrıya bağlanmayı', 'Zorla yapılan eylemi'], 'Akrasia, kişinin doğru eylemi bildiği hâlde tutkusuna yenik düşmesidir. Bu kavram Sokrates\'in "kimse bile bile kötülük yapmaz" görüşüne bir itiraz sayılır.'),
  ('Aristoteles\'in "Politika"da orta sınıfın güçlü olduğu devletler hakkındaki görüşü nedir?', 'Aşırı zenginlik ve yoksulluk uçlarının ortası olduğu için en kararlı olurlar', ['Savaşta her zaman başarısız olurlar', 'Tiranlıklara en çok yatkın olurlar', 'Hiç yasa gerektirmezler'], 'Aristoteles, orta sınıfın aşırılıkların arasında dengeleyici olduğunu ve onlarca yönetilen kentlerin daha istikrarlı olduğunu savunur.'),
  ('Aristoteles\'in "Retorik"te belirttiği üç söylem türünden "adli" söylem hangi alanda kullanılır?', 'Mahkemede geçmiş eylemleri savunma ve suçlama', ['Halk meclisinde gelecekle ilgili kararları tartışma', 'Cenaze törenlerinde övgü', 'Tiyatroda oyunculuk'], 'Aristoteles söylevleri siyasal (geleceğe), adli (geçmişe) ve gösterişli (övgü-yergi) olarak üçe ayırır.'),
  ('Aristoteles\'in köleliğe ilişkin tartışmalı görüşü nedir?', 'Bazı insanların doğuştan köle olduğunu savunması', ['Kölelerin hiç ayrım gözetmeksizin özgür olması gerektiğini', 'Köleliğin yalnız savaş sonucu olduğunu söylemesi', 'Köleliğin tümüyle kaldırılması gerektiğini söylemesi'], 'Aristoteles "Politika"da bazı insanları doğal köle sayar; bu, antik toplumun önyargısını yansıtan ve sonradan çok eleştirilen bir görüştür.'),
  ('Epikurosçuluğun atomculuğa eklediği ve özgür iradeyi açıklamaya yarayan düşünce nedir?', 'Atomların düz yoldan rastgele sapması', ['Atomların çürüyüp yok olması', 'Atomların tanrı iradesiyle sürekli yönlendirilmesi', 'Atomların yalnız dairesel hareket etmesi'], 'Demokritos\'un katı determinizminden kaçınmak için Epikuros atomların düşerken sapabildiğini kabul eder. Bu sapma özgür iradeye alan açar.'),
  ('Epikuros\'a göre adalet nedir?', 'Birbirine zarar vermemek için yapılan karşılıklı bir anlaşma', ['Tanrılar tarafından konan, hiçbir koşulda değişmeyen ve her toplumda aynı olan mutlak bir yasadır', 'Güçlünün zayıf üzerindeki hakkı', 'İdealar dünyasındaki bir ilke'], 'Epikuros adaleti doğa gereği var olan mutlak bir ilke değil, insanların birbirine zarar vermemek üzere yaptıkları bir sözleşme olarak görür.'),
  ('Epikurosçulukta hazlar arasında "durağan haz" (katastematik haz) neyi ifade eder?', 'Acının ve kaygının bulunmadığı sakin bir ruh ve beden durumunu', ['Yeni bir isteğin doyurulması anında duyulan, kısa süreli ve coşkulu bir hareketli sevinç durumunu', 'Büyük bir ziyafetteki sevinci', 'Siyasi bir zaferden duyulan hazzı'], 'Epikuros\'a göre en yüksek haz, istek ya da acının olmadığı dingin durumdur. Hareketli hazlar ise bu durumu yalnızca çeşitlendirir.'),
  ('Stoa\'nın ikinci kurucusu olarak anılan Khrysippos hangi alanda önemli katkılar yapmıştır?', 'Önermeler mantığı ve Stoa sistemini düzenlemede', ['Doğadaki atom hareketlerini açıklayan atom kuramını geliştirmesinde ve Demokritos\'u izlemesinde', 'Geometride', 'Retorik sanatında'], 'Khrysippos çok sayıda eser yazarak Stoa öğretisini sistemleştirdi ve koşullu ve ayrık önermelerin mantığını geliştirdi. "Khrysippos olmasaydı Stoa da olmazdı" sözü ona atfedilir.'),
  ('Stoacılara göre sağlık, zenginlik ve ün gibi şeyler ahlaki açıdan nasıl bir değerdedir?', 'Kayıtsız şeylerdir (adiaphora); ne iyidirler ne de kötü', ['Bunların tümü mutlaka iyi sayılır ve peşinden gidilmelidir', 'Bunların tümü mutlaka kötü sayılır ve uzak durulmalıdır', 'Yalnızca tanrılara aittir'], 'Stoacılara göre tek iyi erdemdir, tek kötü ise erdemsizliktir. Sağlık, zenginlik gibi şeyler bu açıdan kayıtsızdır ama tercih edilebilir olabilir.'),
  ('Stoacıların "kataleptik izlenim" dedikleri nedir?', 'Kendi gerçekliğini kesin biçimde kabul ettiren, güvenilir kavrayıcı izlenim', ['Rüyada görülen ve kişiyi yanıltan, hiçbir gerçekliği olmayan karışık ve değişken imgeleri', 'Tanrılardan gelen vahiy', 'Yalnız matematiksel bir ispat'], 'Stoacılar bilginin kaynağını duyum izlenimlerinde arar. Bunlardan nesnenin gerçekliğini kendiliğinden kabul ettiren izlenimler bilginin ölçütüdür.'),
  ('Stoacıların "ekpyrosis" öğretisine göre evren sonunda ne olur?', 'Kendisi ateş içinde yok olup yeniden aynı biçimde doğar', ['Sonsuza dek hiçbir değişikliğe uğramadan aynı kalır ve yeni bir evren dönemi başlamaz', 'Su altında kalır', 'Atomlara ayrılıp tanrılara döner'], 'Stoacılar evrenin döngüsel olduğunu savundu. Dönem sonunda her şey ilk ateşe döner (ekpyrosis) ve evren yeniden oluşur.'),
  ('Epiktetos\'un "Seni üzen olaylar değil, olaylar hakkındaki yargılarındır" sözü ne anlama gelir?', 'Duygularımızın kaynağı dış olaylar değil, onlara verdiğimiz anlamdır', ['Hiç kimsenin duygusu olmaz ve duygular yalnızca tanrıların insanlara verdiği bir armağandır', 'Acı çekmek asla doğal değildir', 'Olaylar yalnızca bizim iyiliğimiz için olur'], 'Epiktetos\'a göre etkilenmemizi belirleyen olayın kendisi değil, ona ilişkin düşüncemizdir. Yargıyı değiştirmek duyguyu da değiştirir.'),
  ('Marcus Aurelius\'un felsefi konumunu en iyi ifade eden durum hangisidir?', 'İmparator olarak Stoacı ilkeleri kişisel disiplin için uygulaması', ['Krallıktan tümüyle çekilip bir mağarada yaşayarak devlet işlerine hiç karışmaması ve felsefe öğretmesi', 'Platonculuğu devlet dini ilan etmesi', 'Bütün felsefe okullarını kapatması'], 'Marcus Aurelius, ağır görevleri sırasında Stoacı düşüncelerle kendini eğitmeye çalıştı. Eserinde evrensel akla uyum ve sorumluluk vurgulanır.'),
  ('Septik filozof Pyrrhon\'un ahlaki hedefi olan "ataraksia"ya hangi yolla ulaşılacağını söylediği kavram nedir?', 'Epokhe', ['Apatheia (tutkulardan tümüyle arınma), erdemli yaşamla kazanılır', 'Anamnesis', 'Katharsis'], 'Septiklere göre bir konuda karşıt iddialar eşit güçte olduğundan yargıyı askıya almak gerekir. Bunun sonucu dinginlik (ataraksia) gelir.'),
  ('Pyrrhon\'un gerçekle ilgili öğretisini yazıya geçiren ve onun öğrencisi olan filozof kimdir?', 'Timon', ['Ainesidemos', 'Sextus', 'Arkesilaos'], 'Pyrrhon yazı yazmamış, öğretisini Timon aktarmıştır. Timon\'un hiciv şiirleri Pyrrhoncu görüşlerin başlıca kaynaklarındandır.'),
  ('Septiklere göre günlük yaşamda eylemi neyle yönlendirmek gerekir?', 'Görünüşlere, geleneklere ve doğal eğilimlere uyarak', ['Kesin bilimsel bilgiyle ve her konuda kanıtlanmış genel yasalarla, aklın zorunlu ilkeleriyle', 'Yalnızca tanrısal vahiyle', 'Yalnızca bireysel mantık kurallarıyla'], 'Septikler hiçbir şeyin kesin bilinemeyeceğini söylese de yaşamı sürdürmek için görünüşe ve geleneğe uyarlar. Bu, onlara yönelik "yaşayamazlar" itirazına verilen yanıttır.'),
  ('Yeni Platoncu Plotinos\'un varlık basamaklarının doğru sıralaması hangisidir?', 'Bir, Nous (akıl), Ruh, Madde', ['Madde, Ruh, Nous (akıl), Bir, yani yukarıdan aşağıya taşmanın tam tersi bir sıra', 'Nous, Bir, Madde, Ruh', 'Ruh, Madde, Bir, Nous'], 'Plotinos\'a göre taşma (emanasyon) süreciyle Bir\'den Akıl, Akıldan Ruh, Ruhtan duyulur dünya ve en altta Madde çıkar.'),
  ('Plotinos\'a göre kötülük nedir?', 'İyinin yokluğu, Bir\'den en uzak olan maddenin sonucu', ['Tanrı\'nın yarattığı, bağımsız ve iyiye eşit güçte ikinci bir ilke olduğu', 'Ruhun kendi iradesiyle kurduğu bir varlık', 'Yalnızca insan zihninin ürettiği bir yanılsama'], 'Plotinos kötülüğe ayrı bir varlık tanımaz; onu Bir\'den uzaklaşmanın, yani iyiliğin eksikliğinin sonucu olarak görür.'),
  ('Plotinos\'a göre insan ruhunun amacı olan Bir\'le birleşmeye ne ad verilir?', 'Ekstasis', ['Katharsis, yani acıma ve korku aracılığıyla yaşanan duygusal arınma', 'Entelekheia', 'Anamnesis'], 'Plotinos Bir\'le birleşmeyi akıl yürütmeyle değil, ruhun kendinden geçerek yükselmesiyle mümkün görür. Bu mistik birleşme Yeni Platonculuğun hedefidir.'),
  ('Porphyrios\'un "Isagoge" adlı eseri Orta Çağ düşüncesinde hangi bakımdan önem taşır?', 'Beş tümel öğretisiyle Orta Çağ\'daki evrenseller tartışmasını başlatan, Kategoriler\'e giriş niteliğindeki kitap olması', ['Tanrı\'nın varlığına dair ilk kanıtları sıralayıp Hristiyan öğretisinin resmî düzenlemesi olarak okutulması', 'Bir devlet yönetimi kılavuzu olarak Bizans yöneticilerine yol göstermesi ve siyasal danışmanlık içermesi', 'Hristiyan öğretisinin ilk resmî düzenlemesi sayılarak kilise toplantılarında okutulması'], 'Isagoge Boethius\'un Latinceye çevirmesiyle skolastik mantığın giriş kitabı oldu. Eserdeki tümel sorusu Orta Çağ\'ın en büyük tartışmalarından birini başlattı.'),
  ('Porphyrios\'un "beş tümel" listesinde aşağıdakilerden hangisi yer almaz?', 'Töz', ['Cins', 'Tür', 'İlinek'], 'Porphyrios\'a göre beş tümel cins, tür, ayrım (fark), özgül özellik ve ilinektir.'),
  ('İmparator Justinianus\'un MS 529\'da Atina\'daki felsefe okullarını kapatma kararının felsefe tarihi açısından anlamı nedir?', 'Antik felsefe geleneğinin kurumsal olarak sona ermesinin simgesi sayılır', ['Skolastik yöntemin başlangıcı ve üniversitelerin ilk kez Avrupa\'da kurulmasının simgesi sayılır', 'Hristiyanlığın kabulünün ilk adımı', 'Aristoteles mantığının yasaklanması'], 'Justinianus\'un kararıyla Atina okullarındaki öğretim sona erdi. Bazı filozoflar İran\'a gitti; bu olay genellikle antik dönemin sonu kabul edilir.'),
  ('Tertullianus\'a atfedilen "Atina ile Kudüs\'ün ne ilgisi var?" sorusu hangi tutumu yansıtır?', 'Felsefe ile inancı birbirinden ayırıp felsefeye güvensizlik', ['Felsefeyi inancın tek temeli sayar ve Aristoteles mantığının Hristiyan öğretisine eksiksiz uyduğunu söyler', 'Platonculuğa tam bağlılık', 'Aristoteles mantığını savunma'], 'Tertullianus Yunan felsefesinin sapkınlıkların kaynağı olduğunu savundu ve inancı aklın üzerine koydu. Bu, felsefeye karşı en keskin Hristiyan tutumlardan biridir.'),
  ('İskenderiyeli Origenes\'in Hristiyan düşünce tarihindeki önemi nedir?', 'Hristiyan öğretisini Yeni Platoncu felsefe ile sistemli biçimde yorumlamaya çalışan ilk büyük teologlardan biri olması', ['Hristiyan öğretisini kökten reddedip Yunan çok tanrıcılığına dönülmesini savunması ve kiliseyi eleştirmesi', 'Atomculuk öğretmesi', 'Ortaçağ üniversitesini kurması'], 'Origenes, İncil\'i alegorik yorumladı ve Platonculuğun etkisinde bir sistem kurdu. "Prensipler Üzerine" eseri bu çabanın örneğidir.'),
  ('Kapadokya Babaları olarak anılan düşünürler için hangi görüş doğrudur?', 'Hristiyan teolojisini Yunan felsefesinin kavramlarıyla işleyip Üçleme öğretisini biçimlendirenlerdir', ['Epikurosçu bir cemaat kurup Anadolu\'da atomcu görüşleri öğreten ve Üçleme\'yi reddeden düşünürlerdir', 'Roma hukukunu yazmışlardır', 'Atomcu okulun üyeleridir'], 'Basileios, Nazianzlı Gregorios ve Nyssalı Gregorios Anadolu\'nun Kapadokya bölgesinde yetişip Üçleme (Teslis) öğretisini Yunan felsefe terimleriyle açıkladılar.'),
  ('Pseudo-Dionysios\'un (Areopagitesi) felsefe tarihindeki önemi nedir?', 'Tanrı\'nın ancak olumsuzlama (apofatik) yoluyla anlatılabileceğini savunan Yeni Platoncu Hristiyan metinler bırakması', ['Skolastik yöntemin ilk uygulayıcısı olup Tanrı\'yı yalnız olumlu sıfatlarla tanımlayan öğretiyi başlatması', 'Atomcu şiir yazması', 'Ortaçağ üniversitelerini kurması'], 'Pseudo-Dionysios, Tanrı\'yı sıfatlarla tanımlamak yerine "ne olmadığını" söyleyen olumsuz teolojiyi öne çıkardı. Bu görüş Orta Çağ mistisizmini etkiledi.'),
  ('Plotinos\'un varlık sıralamasında "Nous" (akıl) neyi temsil eder?', 'Bir\'den ilk taşan, ideaların bulunduğu ilahi akıl', ['Maddenin kendisini, yani Bir\'den en uzak ve en alçak basamağı', 'Ruhun beden içindeki bölümü', 'Yalnız duyular dünyası'], 'Nous, Bir\'in hemen altındaki ve idealar dünyasını içeren evrensel akıldır. Ondan Dünya Ruhu, ondan da duyulur dünya taşar.'),
  ('Yeni Platoncu felsefenin Hristiyan düşüncesine etkisini en iyi hangisi örnekler?', 'Augustinus\'un Platoncu kavramlarla Hristiyan öğretisini yorumlaması', ['Tertullianus\'un felsefeyi tümüyle reddedip inancı aklın karşısına koyması ve Platonculuğu eleştirmesi', 'Epiktetos\'un köleliği savunması', 'Lucretius\'un atomculuğu'], 'Augustinus Hristiyanlığa geçmeden önce Platoncu kitaplar okumuş, ruhsal bir Tanrı anlayışını bu kaynaktan edinmiştir.'),
  ('Augustinus\'a göre zaman asıl olarak nerede ölçülür?', 'İnsan ruhunda: geçmiş bellekte, gelecek beklentide', ['Gökteki yıldızların hareketinde ve güneşin doğuş ve batışında, yani dış dünyada', 'Takvim ve saat gibi ölçüm aletlerinde', 'Atomların titreşiminde'], 'Augustinus "İtiraflar"da zamanı ruhun uzaması (distentio animi) olarak yorumlar. Geçmiş belleğin, şimdi dikkatin, gelecek beklentinin ruhtaki biçimleridir.'),
  ('Augustinus\'un Pelagius ile tartışmasında savunduğu görüş hangisidir?', 'İnsanın kurtuluşu için Tanrı\'nın lütfu zorunludur', ['İnsan, iyilik için yalnızca kendi çabasıyla yeterlidir', 'İnsanlar doğuştan günahsızdır', 'Günah ve lütuf diye bir şey yoktur'], 'Pelagius insanın kendi iradesiyle erdeme ulaşabileceğini söyledi. Augustinus ilk günahın etkisini vurgulayıp kurtuluşun Tanrı\'nın lütfuna bağlı olduğunu savundu.'),
  ('Augustinus\'un "Yanılıyorsam bile varım" (si fallor, sum) ifadesi hangi sonraki düşünceyle ilişkilendirilir?', 'Descartes\'ın "Düşünüyorum, öyleyse varım" ilkesiyle', ['Locke\'un "zihin doğuştan boş bir levhadır" görüşüyle ve deneyciliğin doğuşuyla', 'Hume\'un nedensellik eleştirisiyle', 'Kant\'ın saf aklıyla'], 'Augustinus kuşku duyan bir varlığın var olduğunu söyler; bu, Descartes\'ın cogito\'sunu önceleyen bir kanıt biçimi olarak anılır.'),
  ('Augustinus\'a göre değişmez ve zorunlu hakikatler zihnimize nasıl ulaşır?', 'Tanrı\'nın ruhu aydınlatması (illuminasyon) yoluyla', ['Yalnızca duyu deneyiminden ve tekrar eden gözlemlerden, yani deneysel genellemelerle', 'Atomların çarpışmasından', 'Toplumsal sözleşmeyle'], 'Augustinus Platoncu etkiyle değişmez hakikatlerin duyularla elde edilemeyeceğini, Tanrı\'nın ışığıyla aydınlanan akılla kavrandığını savundu.'),
  ('Augustinus\'un düşünce geleneği için hangisi doğrudur?', 'Hristiyan öğretisini Platonculukla birleştiren Orta Çağ\'ın temel kaynaklarından biridir', ['Aristoteles mantığını ilk uygulayan, skolastik yöntemin kurucusu ve üniversitelerin başlatıcısıdır', 'Materyalist bir görüştür', 'Skolastik yöntemin kurucusudur'], 'Augustinus\'un Platoncu yönelimi, Aquinas\'a kadar Batı Hristiyan felsefesinin başlıca çerçevesiydi.'),
  ('Boethius\'un "Felsefenin Tesellisi"nde Fortuna\'nın çarkı neyi simgeler?', 'Talih ve servetin değişkenliğini', ['Evrenin döngüsel yaratılışını ve tanrıların yönetimini', 'Kralların mutlak gücünü', 'Ölümden sonraki yargıyı'], 'Felsefe, Boethius\'a talihin sürekli döndüğünü ve onun verdiklerinin kalıcı olmadığını, gerçek mutluluğun kalıcı iyide olduğunu anlatır.'),
  ('Boethius\'un "aeternitas" (sonsuzluk) tanımı neye benzer?', 'Sınırsız yaşamın tamamının aynı anda sahip olunması', ['Sonsuz bir zaman çizgisi boyunca uzayıp giden, başlangıcı ve sonu olmayan zaman', 'Ölümden sonraki yaşam', 'Dünyanın başlangıcından beri geçen süre'], 'Boethius\'a göre Tanrı\'nın sonsuzluğu zamanın sonsuz uzaması değildir; yaşamın tamamının bir anda kavranmasıdır. Bu, ön bilgi ile özgür irade sorununa çözüm sunar.'),
  ('Karolenj dönemi eğitim reformunda Charlemagne\'ın sarayında öne çıkan İngiliz bilgin kimdir?', 'Alcuin', ['Boethius', 'Bede', 'Anselmus'], 'Alcuin, Charlemagne\'ın çağrısıyla saray okulunu düzenledi ve liberal sanatlara dayalı eğitimi yaymaya çalıştı.'),
  ('Isidorus\'un "Etymologiae" adlı eseri hangi işleve sahiptir?', 'Antik bilgiyi toplayan Orta Çağ\'ın ilk büyük ansiklopedilerinden biri', ['Skolastik yöntemin ilk el kitabı olup üniversitelerde mantık dersi için yazılmış bir mantık özeti', 'Tanrı\'nın varlığına dair bir kanıt', 'Roma hukuk kuralları derlemesi'], 'Sevilla piskoposu Isidorus, sözcüklerin kökenleri üzerinden antik bilgiyi bir araya getirerek Orta Çağ boyunca kullanılan bir başvuru yapıtı bıraktı.'),
  ('Eriugena\'nın "Doğanın Bölünüşü" (Periphyseon) adlı eserinde "doğa" ne anlama gelir?', 'Yaratıcıyı ve yaratılanı da kapsayan bütün varlık', ['Yalnızca maddi dünya, yani gözle görülen ve duyuyla algılanan şeyler topluluğu', 'Yalnızca insanın doğası', 'Yalnızca bitkiler ve hayvanlar'], 'Eriugena doğayı hem Tanrı\'yı hem evreni kapsayan bütünlük olarak görür ve dört bölüme ayırır. Bu görüş Yeni Platoncu etkiyi gösterir.'),
  ('Skolastik felsefede "evrenseller sorunu"nun özü hangisidir?', 'Cins ve tür gibi genel kavramların gerçekten var olup olmadığı', ['Tanrı\'nın tek mi yoksa çok mu olduğu sorusu ve onun sıfatlarının sayısı', 'Zamanın başlangıcı olup olmadığı', 'Maddenin atomlardan oluşup oluşmadığı'], 'Evrenseller sorunu, "insan", "güzellik" gibi genel kavramların nesnel bir gerçeklik mi yoksa yalnızca zihinsel ya da dilsel adlar mı olduğunu sorar.'),
  ('Roscelinus\'un "flatus vocis" (sesin soluğu) sözüyle savunduğu görüş hangisidir?', 'Evrensellerin yalnızca adlardan ibaret olduğu', ['Evrensellerin tek gerçek varlık olduğu ve bireylerin yalnızca gölge olduğu', 'Evrensellerin zihinde kavramlar olarak var olduğu', 'Evrensellerin Tanrı\'nın düşüncesinde olduğu'], 'Roscelinus\'a göre cinsler ve türler gerçek varlıklar değil, yalnızca sözcüklerdir. Bu görüş nominalizmin erken biçimidir.'),
  ('"Universalia ante rem, in re, post rem" ayrımında "in re" neyi ifade eder?', 'Evrenselin bireysel nesnelerin içinde bulunduğunu', ['Evrenselin bireysel nesnelerden önce, Tanrı\'nın zihninde var olduğunu', 'Evrenselin nesnelerden sonra zihinde oluştuğunu', 'Evrenselin hiç var olmadığını'], 'Aristotelesçi yorum evrensellerin nesnelerin içinde formlar olarak var olduğunu söyler. Ante rem Platoncu, post rem nominalist yönü temsil eder.'),
  ('Abelard\'ın "Sic et Non" (Evet ve Hayır) adlı eserinde uyguladığı yöntem nedir?', 'Kilise babalarının çelişen görüşlerini yan yana koyup akıl yürütmeyle uzlaştırmaya çalışmak', ['Kutsal metni ve kilise babalarının sözlerini hiç sorgulamadan, olduğu gibi aktarmak ve çelişkilerini yok saymak', 'Doğayı deneyle incelemek', 'Her konuda yalnızca vahyi izlemek'], 'Abelard çelişen otorite görüşlerini karşılaştırıp kuşkunun gerçeğe götürdüğünü söyledi. Bu yöntem skolastik tartışmanın temelini hazırladı.'),
  ('Abelard\'ın etiğinde ahlaki değeri belirleyen şey nedir?', 'Eylemin değil, niyetin (vicdan) ahlaki değeri belirlemesi', ['Yalnızca eylemin sonucunun ve toplum üzerindeki etkisinin ahlaki değeri belirlemesi', 'Yalnızca toplumun beklentisi', 'Yalnızca yasanın yazısı'], 'Abelard "Kendini Bil" adlı eserinde günahı niyette ve vicdanın rızasında görür. Aynı eylem farklı niyetlerle farklı değer taşır.'),
  ('Chartres\'lı Bernard\'a atfedilen "Biz devlerin omuzlarında duran cüceleriz" sözü neyi anlatır?', 'Sonraki kuşakların, öncekilerin birikimi sayesinde daha uzağı görebildiğini', ['İnsanların devlerden küçük olduğunu ve eskilerin her konuda hep haklı olduğunu', 'Cücelerin devlerden daha güçlü olduğunu', 'Yeni bilgilerin değersizliğini'], 'Söz, geçmiş bilginin üzerine kurularak ilerleme olabileceğini anlatır. Orta Çağ bilginleri bu sözle antik mirasa bağlılığı vurgulardı.'),
  ('Petrus Lombardus\'un "Sententiae" adlı derlemesi Orta Çağ üniversitelerinde nasıl kullanılmıştır?', 'Teoloji öğretiminin temel ders kitabı olup üzerine şerhler yazılmıştır', ['Hukuk davalarında delil olarak okunmak ve kentin yasalarını belirlemek amacıyla', 'Yalnızca manastır duaları için', 'Kentin yasaları olarak'], 'Lombardus\'un dört kitaplık "Sententiae"sı yüzyıllarca teoloji öğretiminin başucu kitabıydı; Aquinas ve Ockham gibi düşünürler onun üzerine şerh yazdı.'),
  ('Orta Çağ üniversitesinde "sanat fakültesi" öğrencileri hangi amaçla eğitim görürdü?', 'Teoloji, hukuk ya da tıp fakültelerine geçmeden önceki temel eğitim için', ['Doğrudan papaz olabilmek için gerekli dinsel ayinleri öğrenmek ve manastıra girmeye hazırlanmak için', 'Savaş sanatı öğrenmek için', 'Ressam ve heykeltıraş yetişmek için'], 'Sanat fakültesi liberal sanatları ve mantığı öğretir, öğrenciler daha sonra teoloji, hukuk veya tıp gibi üst fakültelere geçerdi.'),
  ('Skolastik yöntemin "disputatio" (tartışma) uygulaması neyi içerir?', 'Bir soru hakkında karşıt görüşlerin ileri sürülüp tartışılarak sonuca varılmasını', ['Yalnız bir metnin yüksek sesle okunmasını ve öğrencilerin onu ezberden tekrar etmesini', 'Öğrencinin ezber yapmasını', 'Kralın karar vermesini'], 'Disputatio\'da bir soru ortaya atılır, karşıt savlar ve otoriteler sıralanır, sonra üstat çözümünü ve itirazlara yanıtlarını verir.'),
  ('Aquinas\'ın "Summa Theologiae" adlı eserinin her bölümü hangi yapıyla ilerler?', 'Soru, itirazlar, karşıt görüş, çözüm ve itirazlara yanıtlar', ['Yalnızca kesintisiz düz anlatım, hiçbir itirazın ele alınmadığı biçimde', 'Şiir biçiminde dörtlükler', 'Diyalog biçiminde konuşmalar'], 'Summa her konuyu "quaestio" biçiminde ele alır: önce itirazlar, sonra "sed contra" denen karşıt otorite, sonra yanıt ve itirazlara cevaplar gelir.'),
  ('Paris Piskoposu Tempier\'in 1277\'de yasakladığı önermeler neyle ilgilidir?', 'Aristotelesçi ve İbn Rüşdçü bazı öğretilerin Hristiyan inancına aykırı biçimde öğretilmesiyle', ['Matematiğin ve müziğin üniversitelerde öğretilmesiyle ve bunların kilise ayinlerinden ayrılmasıyla', 'Yeni kiliselerin kurulmasıyla', 'Bütün kitapların yasaklanmasıyla'], '1277\'de Tempier\'in kınadığı yüzü aşkın önerme, felsefenin teolojiden bağımsız hakikat iddiası taşıyan öğretilerini hedefliyordu. Aquinas\'ın bazı görüşleri de bu kapsamda tartışıldı.'),
  ('Aquinas\'ın "varlık ve öz" (essentia–esse) ayrımı neyi anlatır?', 'Yaratılmış varlıklarda varoluş, özden ayrı bir ilkedir; yalnızca Tanrı\'da öz ve varoluş birdir', ['Her varlıkta öz ile varoluşun aynı şey olduğunu ve ikisinin birbirinden hiçbir biçimde ayrılamayacağını', 'Varoluşun yalnızca insanlara özgü olduğunu', 'Özün yalnızca zihinde bulunduğunu'], 'Bir şeyin ne olduğu ile var olması farklı şeylerdir. Yalnız Tanrı\'nın özü varoluşuyla özdeştir; diğer varlıklar varlığı Tanrı\'dan alır.'),
  ('Aquinas\'ın "analogia entis" (varlık analojisi) öğretisi neyi söyler?', 'Tanrı\'ya ilişkin sözcükler tek anlamlı değil, benzerlik ve ilişki yoluyla anlamlıdır', ['Tanrı\'ya ilişkin her söz, insan sözcüklerinin anlamıyla tam ve birebir doğrudur, aralarında fark yoktur', 'Tanrı\'ya ilişkin hiçbir söz anlamlı değildir', 'Tanrı ve insan aynı türdendir'], '"İyi", "bilge" gibi sözcükler Tanrı için ve insan için tamamen aynı ya da tamamen farklı anlamda değil, benzer anlamda kullanılır.'),
  ('Aquinas akıl ve iman arasındaki ilişkiyi nasıl görür?', 'Vahiy ve akıl aynı Tanrı\'dan geldiği için çelişmezler; akıl vahyin hazırlığıdır', ['İkisi birbiriyle sürekli çelişir ve bu yüzden birinden vazgeçmek zorunludur, çünkü kaynakları farklıdır', 'Yalnız akıl doğrudur', 'Yalnız vahiy doğrudur ve akıl yasaktır'], 'Aquinas\'ın "lütuf doğayı ortadan kaldırmaz, tamamlar" ilkesi, aklın ve imanın uyum içinde olduğunu gösterir.'),
  ('Aquinas\'ın Aristoteles\'in felsefesine tutumu nasıldır?', 'Aristoteles\'i yorumlayıp Hristiyan öğretisiyle uyumlu bir sistem kurmaya çalışmıştır', ['Aristoteles\'i yasaklayıp tümüyle yok saymış ve yalnızca Augustinus\'un Platoncu çizgisine bağlı kalmıştır', 'Yalnızca Platon\'u izlemiştir', 'Aristoteles\'i tanrı saymıştır'], 'Aquinas Aristoteles\'e "Filozof" diyecek kadar değer verdi, ama onun görüşlerini Hristiyan düşünceyle bağdaştırmak için düzeltti.'),
  ('Aquinas\'a göre "adil savaş"ın koşullarından biri aşağıdakilerden hangisidir?', 'Meşru otoritece açılmış olması ve haklı bir nedene dayanması', ['Yalnız zenginlik ve toprak elde etmek için yapılması ve tarafların kendi çıkarını gözetmesi', 'Papa\'nın izni olmadan yapılması', 'Hiçbir kural gözetmemesi'], 'Aquinas adil savaş için meşru yetki, haklı neden ve doğru niyet koşulunu belirtir. Bu görüş sonraki savaş hukuku düşüncesini etkiledi.'),
  ('Ockhamlı William\'ın Papa XXII. John ile çatışmasının konusu hangisidir?', 'Fransisken tarikatının mülksüzlük ilkesi ve papalığın yetki sınırları', ['Üniversitelerin açılması ve ders programlarına mantık eğitiminin eklenmesi konusundaki ayrılıklar', 'Haçlı seferlerinin finansmanı', 'Evrenin yaşı'], 'Ockham, Fransiskenlerin yoksulluk ilkesini savunarak Papa\'ya karşı çıktı, aforoz edildi ve Alman İmparatoru\'nun himayesine sığındı. Papanın dünyevi yetkilerinin sınırlı olduğunu savundu.'),
  ('Jean Buridan\'ın "impetus" kavramı neyi açıklamak için geliştirilmiştir?', 'Fırlatılan cismin, fırlatıldıktan sonra da hareket etmeyi sürdürmesini', ['Gezegenlerin yörüngelerinin neden daire biçiminde olduğunu ve neden sabit kaldığını', 'Suyun kaynamasını', 'Yıldızların ışığını'], 'Buridan, Aristoteles\'in havanın itmesiyle açıklamasına karşı, hareket ettiricinin cisme geçici bir güç (impetus) verdiğini savundu. Bu, ileride eylemsizlik anlayışına yaklaşır.'),
  ('Buridan\'ın eşeği örneği hangi felsefi soruna işaret eder?', 'Eşit seçenekler karşısında iradenin karar verememe sorununa', ['Hayvanların ruhunun olup olmadığı ve bu ruhun beden ölünce yok olup olmayacağı sorununa', 'Evrenin sonsuzluğuna', 'Zamanın başlangıcına'], 'Eşit uzaklıkta iki yem arasında kalan aç eşek karar verememe nedeniyle açlıktan ölür. Örnek irade ve seçim tartışmalarında kullanılır; Buridan\'a atfedilir.'),
  ('Roger Bacon bilgiye ulaşma yolu olarak neyi öne çıkarır?', 'Deney ve gözlem', ['Yalnızca otoritelere bağlılık ve eski metinlerin sorgusuz biçimde tekrar edilmesi', 'Yalnızca vahiy', 'Yalnızca tartışma'], 'Bacon, "Opus Majus"ta matematik ve deneyin kanıt için gerekli olduğunu vurgular; optik ve mercekler üzerine de çalışmıştır.'),
  ('Robert Grosseteste\'nin doğa felsefesinde evrenin temel ilkesi olarak gördüğü şey nedir?', 'Işık', ['Su', 'Toprak', 'Boşluk'], 'Oxford\'lu Grosseteste ışığı maddenin ilk biçimi ve evrenin oluşumunun temeli sayan bir ışık metafiziği geliştirdi; ayrıca deneysel yöntemin gelişmesine katkı yaptı.'),
  ('Oxford\'daki Merton Koleji\'nde çalışan "Oxford Hesaplayıcıları"nın (Bradwardine ve diğerleri) bilim tarihindeki katkısı nedir?', 'Hareketi ve hızı niceliksel olarak ifade eden kuramlar geliştirmeleri', ['Atomu bölerek maddenin en küçük parçasına ulaşmaları ve atom kuramını kanıtlamaları', 'Teleskop yapmaları', 'Suyun kaynama noktasını bulmaları'], 'Hesaplayıcılar, düzgün ivmeli hareketin ortalama hız kuralı gibi sonuçlara ulaştı. Bu çalışmalar sonradan Galileo\'ya uzanan kinematiğe ön hazırlık oldu.'),
  ('Padovalı Marsilius\'un "Defensor Pacis" (Barışın Savunucusu) adlı eserinde egemenlik kimdedir?', 'Halkta', ['Papada ve onun atadığı piskoposlar kurulunda, yasayı yalnızca onlar koyar', 'Tanrı tarafından atanan tek kralda', 'Soylu sınıfta'], 'Marsilius yasanın gücünü halktan alan bir egemenlik anlayışı geliştirdi ve kilisenin dünyevi yetkisini reddetti. Bu görüş modern siyasi düşünceyi önceler.'),
  ('Orta Çağ Bizans düşüncesinde Mikhail Psellos\'un önemi nedir?', 'Platon\'u ve Yeni Platonculuğu yeniden canlandıran bir bilgin olması', ['Skolastik yöntemi kurup üniversite sistemini oluşturan, mantık dersini yeniden başlatan kişi olması', 'Atomculuğu yeniden öğretmesi', 'Tıp okulunu kurması'], '11. yüzyıl Bizans\'ında Psellos felsefe ve Platon çalışmalarını yeniden başlattı; Konstantinopolis Üniversitesi\'nde felsefe başkanı olarak görev yaptı.'),
  ('Hesykhasm olarak bilinen Bizans mistik akımı neyi önemser?', 'İç dinginlik ve kesintisiz duayla Tanrı\'yla doğrudan deneyim', ['Bilimsel gözlem ve deneyle doğa yasalarını bulmaya çalışmak, dinsel yaşamdan tümüyle ayrı biçimde', 'Siyasi örgütlenme', 'Hukuk yazımı'], 'Gregorios Palamas bu akımın düşünsel savunucusudur; Tanrı\'yı bilgiyle değil, dua ve sessizlikle deneyimlemeyi öğütler.'),
  ('İslam dünyasında Yunanca felsefe ve tıp yazılarını Arapçaya çeviren ve dil bilgisine hâkim ünlü Nasturi çevirmen kimdir?', 'Huneyn b. İshak', ['Sabit b. Kurra', 'İbn Rüşd', 'Gazali'], 'Huneyn b. İshak Galenos\'un ve Aristoteles\'in birçok eserini Süryanice ya da Arapçaya çevirdi; çeviri tekniği ve terim oluşturma çalışmalarıyla tanınır.'),
  ('Kindi\'nin bilimler tarihindeki ayırt edici özelliği nedir?', 'Felsefe, matematik, optik, müzik ve tıp gibi birçok alanda yazması', ['Yalnızca fıkıh yazması', 'Yalnızca şiir yazması', 'Hiç eser yazmaması'], 'Kindi felsefeyle birlikte matematik, astronomi, optik ve müzik teorisi alanında da eser verdi. Bu yüzden ansiklopedik bir bilgin sayılır.'),
  ('Ebubekir er-Razi\'nin Hakim olarak hekimlikte yaptığı önemli ayrım hangisidir?', 'Çiçek ve kızamığı birbirinden ayırması', ['Kanın dolaşımını bulması ve damarların keşfi', 'Mikropları keşfetmesi', 'Anesteziyi bulması'], 'Razi, çiçek ve kızamığı ayrı hastalıklar olarak ilk açıklayan hekimlerdendir. "Kitabü\'l-Havi" ve "Kitabü\'l-Cüderi ve\'l-Hasbe" yapıtları bu alandadır.'),
  ('Razi\'nin "beş ezeli ilke" öğretisinde bunlar nelerdir?', 'Yaratıcı, ruh, ilk madde, mekân ve zaman', ['Ateş, su, hava, toprak ve boşluktan oluşan dizi', 'Akıl, nefs, bedenler, sayı ve uyum', 'Güneş, ay, yıldızlar, yer ve gök'], 'Razi, Platoncu ve atomcu etkilerle evrende beş ezelî ilkenin bulunduğunu söyler. Bu görüş, İslam felsefesinde alışılmışın dışındadır.'),
  ('İhvan-ı Safa\'nın yazdığı "Resail" hangi nitelikte bir eserdir?', 'Felsefe, bilim ve dini birleştiren ansiklopedik risaleler topluluğu', ['Yalnızca fıkıh kitabı', 'Yalnızca şiir derlemesi', 'Yalnızca askeri el kitabı'], 'Basra\'da 10. yüzyılda gizli bir topluluk olan İhvan-ı Safa\'nın yazdığı 52 risale matematik, doğa, ruh ve ilahiyat konularını kapsar.'),
  ('Farabi\'nin "faal akıl" (akl-ı faal) kavramı neyi açıklar?', 'İnsan aklının bilmeyi potansiyelden fiile geçiren, ayrık ilahi akıl', ['Yalnızca duyu algısını', 'Atomların hareketini', 'Yalnızca ahlaki erdemi'], 'Faal akıl, insan aklına bilgiyi veren ve ona ilkeleri aydınlatan en son akıldır. Farabi\'ye göre insan aklı bununla birleşerek bilgiye ulaşır.'),
  ('Farabi\'nin siyaset felsefesinde "cahil şehir" neyi ifade eder?', 'Mutluluğun gerçek anlamını bilmeyip hazza ya da güce yönelen toplum', ['Okuma yazma bilmeyen toplum', 'Savaşta yenilmiş toplum', 'Hiç yasası olmayan toplum'], 'Farabi\'ye göre cahil şehirlerde insanlar zenginlik, haz, şeref gibi amaçları gerçek mutluluk sayar. Erdemli şehir ise gerçek mutluluğa yönelir.'),
  ('Farabi\'nin "Tahsilü\'s-Saade" eserinin konusu nedir?', 'Mutluluğu kazanmanın yolu olarak bilgi ve erdemi', ['Tıp ve hekimlik bilgisini aktaran, hastalıkların sınıflandırılması', 'Astronomi', 'Edebiyat'], 'Eserde Farabi mutluluğa ulaşmanın teorik erdem, düşünsel erdem, ahlaki erdem ve pratik sanatlar yoluyla olacağını anlatır.'),
  ('Farabi\'nin Platon ve Aristoteles hakkındaki tutumu nasıldır?', 'İkisinin görüşlerini uzlaştırmaya çalışmıştır', ['Aristoteles\'i reddedip yalnızca Platon\'u izlemiştir', 'Platon\'u reddedip yalnızca Aristoteles\'i izlemiştir', 'İkisinin de yanlış olduğunu söylemiştir'], 'Farabi "İki Filozofun Görüşlerinin Uzlaştırılması" gibi çalışmalarıyla, Platon ve Aristoteles arasında temel bir çelişki olmadığını göstermeye çalıştı.'),
  ('Farabi\'ye göre dilin mantığa ilişkisi nasıldır?', 'Mantık, bütün dillerde geçerli akıl kurallarını inceler; dil bilgisi ise belirli bir dilin kurallarını', ['Mantık ile dil bilgisi aynı şeydir', 'Mantığın dilden hiçbir ilgisi yoktur', 'Dil bilgisinin mantığa dayandığı'], 'Farabi, mantığı evrensel düşünce biçimlerinin bilimi, dil bilgisini tek bir dilin düzeni olarak ayırır. Bu ayrım mantık-dil bilgisi tartışmalarına zemin oldu.'),
  ('İbn Sina\'nın ruh anlayışında ruhun bedenle ilişkisi hangisidir?', 'Ruh bedenden ayrı bir tözdür; beden ölünce yok olmaz', ['Ruh bedenin bir parçasıdır ve onunla birlikte yok olur', 'Ruh yalnızca kandır', 'Ruh yalnızca beyin hareketidir'], 'İbn Sina "uçan adam" gibi düşünce deneyleriyle ruhun maddeden bağımsız, ölümsüz bir töz olduğunu savunur.'),
  ('İbn Sina\'ya göre insan aklının bilgiye ulaşma sürecinde "heyulani akıl" aşaması neyi ifade eder?', 'Henüz hiçbir şeyi bilmeyen, yalnız bilme yeteneği taşıyan akıl', ['Tam bilgiye ulaşmış akıl', 'Yalnızca duyularla çalışan akıl', 'Tanrı\'nın aklı'], 'İbn Sina akıl derecelerini heyulani, bilmelekeye sahip, bilfiil ve müstefad akıl olarak sıralar. Heyulani akıl boş bir yeti gibidir.'),
  ('İbn Sina\'nın "ortak duyu" (hiss-i müşterek) kavramı ne işe yarar?', 'Beş duyudan gelen verileri birleştirip bir bütün hâline getirmek', ['Yalnızca işitmeyi sağlamak', 'Yalnızca düşünmeyi sağlamak', 'Yalnızca hatırlamayı sağlamak'], 'İbn Sina içsel duyuları ortak duyu, hayal, vehim, hafıza gibi yetilere ayırır. Ortak duyu, duyu verilerini toplar.'),
  ('İbn Sina\'nın "öz–varoluş (mahiyet–vücud) ayrımı" Orta Çağ Latin düşüncesinde hangi düşünürü etkilemiştir?', 'Thomas Aquinas', ['Boethius', 'Eriugena', 'Roscelinus'], 'İbn Sina\'ya göre varlıkların özü ile varoluşu farklıdır; yalnız Tanrı\'da ikisi birdir. Bu fikir Aquinas\'ın essentia-esse ayrımının önemli kaynağıdır.'),
  ('İbn Sina\'nın sudur kuramı ile Farabi\'nin sudur kuramının ortak yanı hangisidir?', 'İkisi de Tanrı\'dan akılların ve gök kürelerinin taştığını söyler', ['İkisi de evrenin atomlardan oluştuğunu söyler', 'İkisi de maddeyi ezeli yaratıcı sayar', 'İkisi de Tanrı\'yı reddeder'], 'Hem Farabi hem İbn Sina Yeni Platoncu sudur şemasına, yani birden birin çıktığı akıllar sırasına dayanır. İbn Sina ayrıntıları kendi sistemine göre değiştirir.'),
  ('Gazali\'nin nedensellik eleştirisinde pamuk ve ateş örneği neyi göstermek içindir?', 'Ateşle temas ile yanma arasında gözlenen ardışıklık zorunlu bir bağ kanıtlamaz; olayı Tanrı yaratır', ['Ateşin her zaman yaktığını', 'Pamuğun yanmaz olduğunu', 'Ateşin yok olduğunu'], 'Gazali, nedenle sonuç arasında gözlediğimiz bağın "alışkanlık" olduğunu, asıl nedenin Tanrı\'nın iradesi olduğunu savunur. Bu, mucizelerin mümkünlüğünü korumaya yarar.'),
  ('Gazali\'nin nedensellik görüşü hangi modern düşünürün eleştirisine benzetilir?', 'David Hume', ['Immanuel Kant', 'Francis Bacon', 'Thomas Hobbes'], 'Gazali nedenselliği zorunlu bağ olarak görmeyip alışkanlığa yaklaşan açıklama yapar; Hume da nedenselliği alışkanlık olarak yorumlar.'),
  ('Gazali\'nin "İhya-u Ulumi\'d-din" adlı yapıtı hangi konuyu işler?', 'Din bilgisini ahlak ve tasavvufla birleştirerek dinî yaşamın canlandırılmasını', ['Mantık kuralları', 'Gökbilimi tablolarını', 'Tıp bilgisini'], '"Dinî ilimlerin canlandırılması" anlamına gelen eser ibadet, âdetler, kötü huylar ve kurtarıcı erdemler olmak üzere dört bölümdür.'),
  ('İbn Tufeyl\'in İbn Rüşd ile bağlantısı hangisidir?', 'İbn Rüşd\'ü Muvahhid halifesine tanıtıp Aristoteles şerhlerine yönlendirmiştir', ['İbn Rüşd\'ün düşmanı olmuştur', 'İbn Rüşd\'ün öğrencisi olmuştur', 'Birbirlerini hiç tanımamışlardır'], 'İbn Tufeyl halife Ebu Yakub\'un sarayında hekim ve vezirdi; İbn Rüşd\'ü ona tanıtarak Aristoteles şerhlerini yazmaya yönlendirdi.'),
  ('İbn Rüşd, Aristoteles şerhlerini kaç düzeyde yazmıştır?', 'Büyük, orta ve küçük şerhler olmak üzere üç düzeyde', ['Yalnızca tek bir özet olarak, kısa bir derleme biçiminde', 'Yalnızca şiir olarak', 'Hiç şerh yazmamıştır'], 'İbn Rüşd yapıtlarının ayrıntısına göre farklı uzunluklarda üç tür şerh kaleme aldı. Bu yüzden Latin Batı onu "Şarih" olarak tanıdı.'),
  ('İbn Rüşd\'ün ünlü fıkıh kitabı hangisidir?', 'Bidayetü\'l-Müctehid', ['Faslü\'l-Makal', 'Tehafütü\'t-Tehafüt', 'Kulliyat'], 'İbn Rüşd hem filozof hem hekim hem de Kordoba kadısıydı. Mezhepler arası karşılaştırmalı fıkıh kitabı Bidayetü\'l-Müctehid onun eseridir.'),
  ('İbn Rüşd\'ün 1195\'te yaşadığı sürgün nedir?', 'Halife tarafından Lucena\'ya sürülmesi ve felsefe kitaplarının yakılması', ['Haçlıların onu esir alması', 'Atina\'ya gitmesi', 'Papa tarafından aforoz edilmesi'], 'Muvahhid halife siyasi koşullar yüzünden felsefe karşıtı çevrelerin baskısına boyun eğdi; İbn Rüşd\'ün kitapları yakıldı ve kendisi Lucena\'ya sürüldü.'),
  ('İbn Rüşd\'ün "Kulliyat" adlı eseri hangi alana aittir?', 'Tıp', ['Mantık', 'Siyaset', 'Şiir'], 'İbn Rüşd\'ün genel tıp kitabı Kulliyat, Latinceye "Colliget" adıyla çevrilerek Avrupa\'da okundu.'),
  ('Sühreverdi\'nin "Hikmetü\'l-İşrak" adlı eserinde bilgiye ulaşmada hangi yola ağırlık verilir?', 'Mantığın yanında iç aydınlanma ve sezgi', ['Yalnızca duyu deneyimi ve gözlemle bilgi edinme yolunu', 'Yalnızca tanım ve kıyas', 'Yalnızca otoriteye bağlılık'], 'Sühreverdi, mantığı gerekli ama yetersiz sayar; ruhsal arınma yoluyla gelen aydınlanma ve sezgiyi bilginin zirvesi sayar.'),
  ('İbn Arabi\'nin "Fusûsu\'l-Hikem" adlı eseri hangi anlayışı işler?', 'Peygamberlerin hikmetleri üzerinden varlık ve bilgi görüşünü', ['Mantık kuralları', 'Askerî stratejiyi', 'Tıp bilgisini'], 'Eser, her peygambere özgü bir hikmeti ele alarak varlık, insan ve Tanrı ilişkisini tasavvufi bir dille anlatır.'),
  ('İbn Arabi\'nin "insan-ı kâmil" kavramı neyi anlatır?', 'Tanrı\'nın isim ve sıfatlarının bütün olarak yansıdığı olgun insan', ['Atomun en küçük parçası', 'İdeal bir devlet başkanı', 'Gök kürelerinin akılları'], 'İnsan-ı kâmil, evrenin özeti sayılan, ilahi isimlerin hepsini içinde taşıyan örnek insandır. Bu kavram sonraki tasavvufu derinden etkiledi.'),
  ('Mevlana\'nın "Mesnevi"sinin ilk bölümünde "Dinle neyden" diye başlayan ney hikâyesi neyi simgeler?', 'Kaynağından ayrı düşen insan ruhunun ayrılık acısını ve özlemini', ['Mevsimlerin değişimini', 'Askerlerin savaşa gidişini', 'Çobanların çalgısını'], 'Ney, kamışlıktan koparılan bir çalgı olarak ruhun ilahi kaynağından uzaklığını ve yeniden dönme özlemini anlatır.'),
  ('Ahmed Yesevi\'nin Türk tasavvuf geleneğindeki önemi nedir?', 'Türkçe "Hikmet"leriyle halkın diliyle tasavvufu yaymış ve Yeseviliğin kurucusu olması', ['Mantığı Latinceye çevirmesi', 'Atomculuğu öğretmesi', 'Bir devlet kurması'], 'Ahmed Yesevi Orta Asya\'da Türkçe şiirlerle tasavvufu halka anlattı. Yeseviye tarikatı Anadolu\'ya kadar yayıldı.'),
  ('Mutezile\'nin "beş esas"ından hangisi, Tanrı\'nın kullarına adil davrandığını ve kötülüğün Tanrı\'dan gelmediğini vurgular?', 'Adl', ['Tevhid', 'Va\'d ve vaid', 'Emr bi\'l-ma\'ruf'], 'Mutezile tevhid, adl, va\'d ve vaid, el-menzile beyne\'l-menzileteyn ve emr bi\'l-ma\'ruf nehy ani\'l-münker ilkelerini benimser. Adl ilkesi insanın özgür iradesini savunur.'),
  ('Mâtürîdî ekolünün kurucusu Ebu Mansur el-Mâtürîdî hangi bölgede yetişmiştir?', 'Semerkant', ['Bağdat\'ta, halifenin sarayının yakınında', 'Basra', 'Endülüs'], 'Mâtürîdî Semerkant\'ta yetişti. Akla Eş\'ari\'den daha fazla yer verir ve akıl yoluyla iyi ile kötünün bilinebileceğini söyler.'),
  ('Nasîrüddîn Tûsî\'nin Meraga Rasathanesi\'ndeki çalışmaları neye yol açmıştır?', 'Astronomi tablolarının (Zic-i İlhani) hazırlanmasına', ['Haçlı Seferlerinin başlamasına ve Kudüs\'ün yeniden fethedilmesine', 'Matbaanın kurulmasına', 'Bir mantık kuramının çürütülmesine'], 'Tûsî, Hülâgû\'nun desteğiyle Meraga\'da rasathane kurdu; burada hazırlanan zijler sonraki gökbilimcileri etkiledi. "Ahlak-ı Nasırî" adlı ahlak eseri de ona aittir.'),
  ('Osmanlı ahlak kitapları geleneğinin ünlü yapıtı olan "Ahlak-ı Alai"nin yazarı kimdir?', 'Kınalızade Ali Çelebi', ['Farabi', 'Gazali', 'İbn Haldun'], 'Kınalızade\'nin "Ahlak-ı Alai"si, Tûsî ve Devvani geleneğini sürdürerek ahlak, aile ve siyaset konularını ele alır.'),
  ('Biruni\'nin bilim tarihindeki özgün katkılarından biri nedir?', 'Dünyanın çevresini gözlem ve hesapla ölçmesi', ['Mikroskobu icat edip mikropları ve bulaşıcı hastalıkları keşfetmesi', 'Matbaayı kurması', 'Suyun kaynama noktasını bulması'], 'Biruni, ufuktaki açı farkı yöntemiyle Dünya\'nın yarıçapını ölçtü; sonuçları modern değerlere çok yakındır.'),
  ('Konfüçyüs\'ün "junzi" (soylu insan, erdemli kişi) kavramıyla neyi vurguladığı doğrudur?', 'Doğuştan soy değil, ahlaki erdem ve eğitimle olgunlaşan insan ideali', ['Doğuştan gelen ayrıcalık', 'Askerî komutanlık', 'Zenginlik'], 'Konfüçyüs "soylu"yu soy sop yerine karakter ve ahlak üzerinden tanımladı. Eğitimle herkesin junzi olabileceğini düşündü.'),
  ('Zhuangzi\'nin "kelebek rüyası" öyküsü hangi felsefi soruyu gündeme getirir?', 'Rüya ile uyanıklık arasındaki ayrımın ve gerçekliğin kesinliğinin sorgulanmasını', ['Devlet yönetimini', 'Savaş stratejisini', 'Ahlak yasalarının kökenini'], 'Zhuangzi bir gün kelebek olduğunu rüyada gördü; uyandığında kelebeğin kendisini mi yoksa kendisinin kelebeği mi rüyada gördüğünü bilemedi. Bu, gerçekliğin göreceliğine işaret eder.'),
  ('Han Fei\'nin temsil ettiği "Legalizm" (Hukukçuluk) okulunda düzen nasıl sağlanır?', 'Katı yasalar, ödül ve cezayla', ['Erdem ve törelerle, ahlaki eğitimle', 'Doğaya uyumla', 'Evrensel sevgiyle'], 'Legalistler insanın bencil olduğunu varsayar ve toplumu ancak açık yasaların, sert cezaların ve ödüllerin düzene sokacağını savunur. Qin devletinin yönetimini etkilemiştir.'),
  ('Çin düşüncesinde "yin ve yang" ilkesi neyi anlatır?', 'Birbirini tamamlayan ve birbirine dönüşen zıt güçlerin dengesini', ['İyi ve kötünün kesin ayrılığını', 'Evrenin yalnız tek ilkeden oluştuğunu', 'Tanrıların savaşını'], 'Yin ve yang karanlık ile aydınlık, dişil ile eril gibi zıt ama karşılıklı bağımlı güçlerdir; evren bu zıtlıkların dengesiyle işler.'),
  ('Daoculukta "dao" (yol) kavramı neyi ifade eder?', 'Evrenin ve doğanın tanımlanamayan, sürekli akan asıl düzenini', ['Bir tanrının adını', 'Bir kentin yasasını', 'Bir ordunun planını'], 'Dao De Jing, Dao\'nun söylenebildiği an gerçek Dao olmadığını söyler; Dao varlığın adlandırılamayan kaynağıdır.'),
  ('Çin\'de "Yüz Okul" (Hundred Schools of Thought) dönemi hangi çağ ile ilişkilendirilir?', 'Ağırlıklı olarak Bahar-Sonbahar ve Savaşan Devletler dönemleriyle', ['Han hanedanının sonuyla', 'Tang döneminin sonuyla', 'Ming döneminin başlangıcıyla'], 'Konfüçyüsçülük, Daoculuk, Mohizm ve Legalizm gibi akımlar MÖ 6.–3. yüzyıllar arasında ortaya çıktı.'),
  ('Konfüçyüsçülükte "li" (tören, uygun davranış) neyi anlatır?', 'Toplumsal ilişkileri düzenleyen töre ve nezaket kurallarını', ['Savaş taktiklerini ve ordunun yürüyüş düzenini belirleyen kuralları', 'Büyü yöntemini', 'Tarım takvimini'], 'Li, bireyin aile ve toplumdaki konumuna uygun davranışını düzenler; ren ile birlikte toplumsal uyum sağlar.'),
  ('Budizmde "sekiz katlı yol" neyi anlatır?', 'Acıdan kurtuluşa götüren doğru görüş, davranış ve zihin eğitimi basamaklarını', ['Sekiz tanrının sıralamasını', 'Sekiz ayrı ibadeti', 'Sekiz kentin yolunu'], 'Sekiz katlı yol doğru görüş, niyet, söz, eylem, geçim, çaba, farkındalık ve odaklanmadan oluşur. Buda\'nın dört yüce gerçeğinden dördüncüsüdür.'),
  ('Budizmde "anatta" (benliksizlik) öğretisi neyi söyler?', 'Değişmeyen sabit bir benlik ya da ruh bulunmadığını', ['Ruhun ölümsüz ve değişmez olduğunu, Tanrı\'nın birliğini ve her şeyin onunla var olduğunu', 'Tanrının birliğini', 'Her insanın bir kast sahibi olduğunu'], 'Buda\'ya göre beden, duygu, algı gibi öğelerin bileşimi dışında değişmez bir "ben" yoktur. Bu, Upanişadların atman anlayışına karşıdır.'),
  ('Buda\'nın "orta yol" öğüdü neyi tavsiye eder?', 'Aşırı hazcılık ile aşırı çilecilik arasında ölçülü bir yaşamı', ['Yalnız çilecilik', 'Yalnız hazcılık', 'Yalnız savaş'], 'Buda sarayda lüks içinde yaşamayı da ağır çileciliği de acıdan kurtulmaya götürmediğini söyleyip ikisi arasında bir yol önerdi.'),
  ('Hint düşüncesinde "samsara" kavramı neyi ifade eder?', 'Doğum, ölüm ve yeniden doğuş döngüsünü', ['Dört mevsimin döngüsünü ve takvim hesabını', 'Bir tapınağın adını', 'Bir kast adını'], 'Samsara ruhun ya da bilinç akışının sürekli yeniden doğduğu döngüdür; amaç bu döngüden kurtulmaktır (moksha ya da nirvana).'),
  ('Hint düşüncesinde "moksha" ne demektir?', 'Doğum-ölüm döngüsünden kurtuluş', ['Bir ayin, tapınakta yapılan tören', 'Siyasi bir görev', 'Askerî rütbe'], 'Moksha, Hinduizm, Jainizm ve Budizm\'de varoluş döngüsünün sona ermesi ve özgürleşme anlamına gelir.'),
  ('Jainizm\'in temel ahlak ilkesi olan "ahimsa" neyi ifade eder?', 'Hiçbir canlıya zarar vermemeyi', ['Savaşı övmeyi', 'Servet toplamayı', 'Yalnızca insana şiddet göstermemeyi'], 'Ahimsa, Jainizm\'de ve Hint ahlak düşüncesinde şiddetsizlik ilkesidir. Jain rahipleri küçük canlıları bile ezmemek için büyük özen gösterir.'),
  ('Bhagavad Gita\'da savaşçı Arjuna\'ya öğütlenen temel ilke hangisidir?', 'Sonucuna bağlanmadan görevini yapmak', ['Savaştan kaçmak ve ailesine dönmek, sonuç gözeterek', 'Yalnız servet biriktirmek', 'Hiçbir şey yapmamak'], 'Krişna, Arjuna\'ya karşılık beklemeden ve bağlanmadan dharma\'sını yerine getirmesini öğütler. Bu, karma yoga olarak anılır.'),
  ('Hinduizmde "dharma" kavramı neyi ifade eder?', 'Evrensel düzen ve kişinin ahlaki görevi', ['Servet toplama ve ticaret yoluyla zenginleşme', 'Bir tanrının adı', 'Bir savaş yöntemi'], 'Dharma hem evrenin düzenini hem de kişinin toplumdaki konumuna uygun ahlaki yükümlülüğünü anlatır.'),
  ('Hint felsefesinde "Vedanta"nın Şankara tarafından geliştirilen kolu (Advaita) neyi öğretir?', 'Tek gerçeğin brahman olduğunu, çokluğun maya (görünüş) olduğunu', ['İki eşit ilkenin varlığını', 'Maddenin tek gerçeklik olduğunu', 'Tanrı olmadığını'], 'Advaita (ikisizlik), brahman\'dan başka gerçek olmadığını söyler; bireysel benlik (atman) aslında brahman ile özdeştir.'),
  ('Sankhya felsefesinin iki temel ilkesi hangileridir?', 'Purusha (bilinç) ve prakriti', ['Brahman ve atman, yani evrensel ve bireysel ruh', 'Yin ve yang', 'Madde ve boşluk'], 'Sankhya, evreni bilincin (purusha) ve maddenin (prakriti) etkileşimiyle açıklayan ikici bir sistemdir; kurtuluş ikisinin ayrımının bilinmesiyle gerçekleşir.'),
  ('Sun Tzu\'nun "Savaş Sanatı" adlı eserinin temel ilkelerinden biri nedir?', 'Savaşmadan düşmanı yenmek en yüksek beceridir', ['Her savaşta çok kayıp vermek ve düşmanı yıpratmak gerekir', 'Savaş hiçbir plan gerektirmez', 'Düşmanı bilmek gereksizdir'], 'Sun Tzu stratejiyi, düşmanı ve kendini bilmeye dayandırır; en iyi zafer çatışmadan elde edilendir.'),
  ('Moşe ben Maymon\'un (Maimonides) Yahudi düşüncesinde felsefe ile Tevrat\'ı uzlaştırmak amacıyla yazdığı kitap hangisidir?', 'Şaşkınlar için Kılavuz', ['Kuzari', 'Hayat Kaynağı', 'İmanlar ve Kanaatler Kitabı'], 'Maimonides, Aristoteles felsefesi ile Tevrat arasında gerilim yaşayan okurlar için "Delâletü\'l-Hâirîn" adlı kitabı yazdı. Kitap Latince çevirileriyle Aquinas\'ı da etkiledi.'),
  ('Maimonides\'in doğduğu ve yaşamının bir bölümünü geçirdiği şehirler hangi seçenekte doğru verilmiştir?', 'Kordoba ve Kahire', ['Atina ve Roma\'da, Latin dünyasında', 'Paris ve Oxford', 'Bağdat ve Buhara'], 'Endülüs\'te Kordoba\'da doğan Maimonides, Muvahhidlerin baskısı üzerine göçüp Fas ve Filistin üzerinden Mısır\'a yerleşti ve Kahire\'de hekimlik yaptı.'),
  ('Antik Yunan\'da "techne" ile "episteme" arasındaki ayrım nedir?', 'Techne yapma becerisi ve uygulamalı bilgi, episteme zorunlu ve genel bilimsel bilgidir', ['İkisi aynı şeydir', 'Techne yalnız şiirdir, episteme yalnız dindir', 'Techne yalnız hukuktur'], 'Techne marangozluk veya hekimlik gibi uygulamalı beceriyi, episteme ise nedenleriyle bilinen kesin bilgiyi anlatır.'),
  ('"Metafizik" sözcüğünün Latince "post physicam" karşılığı olan "ta meta ta physika" ifadesi neyi anlatır?', 'Aristoteles\'in kitap dizisinde Fizik\'ten sonra gelen yapıtları', ['Fiziğe karşı olan bilimi', 'Doğaüstü ayinleri', 'Tıp bilgisini'], 'Rodoslu Andronikos\'un derlemesinde Aristoteles\'in "Fizik\'ten sonra gelen" kitapları, sonradan "metafizik" diye adlandırıldı.'),
  ('Aşağıdaki Yunanca terimlerden hangisi "mutlu yaşam için kendi içinde yeterli olma" anlamına gelir?', 'Autarkeia', ['Ataraksia', 'Apatheia', 'Anamnesis'], 'Autarkeia özellikle Kinikler ve Stoacılarca erdemli bilgenin dış koşullardan bağımsızlığı olarak vurgulandı. Ataraksia ise ruhsal dinginliktir.'),
  ('Anaksimandros\'un felsefe tarihindeki yazı bakımından önemi hangisidir?', 'Doğa üzerine ilk düzyazı felsefi yapıtı yazdığı kabul edilir', ['İlk diyalog yazarıdır', 'İlk şiirsel destanı yazmıştır', 'Hiçbir şey yazmamıştır'], 'Anaksimandros\'un doğa üzerine yazdığı kitap, Yunan felsefesinde düzyazıyla yazılmış ilk metin sayılır; geleneksel şiirsel anlatımın yerini alır.'),
  ('Pythagorasçıları sarsan "ortak ölçüsü olmayan büyüklüklerin" (irrasyonel sayıların) keşfi hangi geometrik örnekle ilişkilendirilir?', 'Karenin kenarı ile köşegeni', ['Çemberin çevresi ile çapı arasındaki oran', 'Üçgenin açıları', 'Küpün yüzeyi'], 'Karenin köşegeninin kenara oranı iki tam sayının oranı olarak yazılamaz. Bu keşif, her şeyin sayıdan ibaret olduğu görüşünü sarstı.'),
  ('Pythagoras teoreminin adı Pythagoras\'tan gelse de tarih araştırmalarına göre bu ilişki hakkında ne söylenir?', 'Babilliler gibi eski uygarlıklarca da biliniyordu', ['Yalnızca Pythagoras biliyordu ve ondan önce hiçbir uygarlık kullanmamıştı', 'Hiçbir uygarlık kullanmıyordu', 'Platon bulmuştu'], 'Dik üçgenin kenar bağıntısı çok eski Mezopotamya ve Mısır uygulamalarında görülür. Pythagorasçılar ise onu kanıtlayıp sistemleştirmiş sayılır.'),
  ('Demokritos\'a göre görme olayı nasıl gerçekleşir?', 'Nesnelerden yayılan ince atom görüntülerinin (eidola) göze ulaşmasıyla', ['Gözden çıkan ışınların cisme dokunmasıyla', 'Tanrının ışık vermesiyle', 'Ruhun gözden çıkıp gezmesiyle'], 'Demokritos duyusal algıyı atom akışıyla açıklar; cisimler eidola denilen ince atom filmleri yayar, bunlar duyu organlarına çarpar.'),
  ('Sofistik bağlamda "eristik" ne anlama gelir?', 'Doğruyu aramak yerine tartışmayı kazanmaya yönelik hileli akıl yürütme', ['Matematik ispat yöntemi', 'Doğa gözlemi', 'Şiir yazma sanatı'], 'Platon "Euthydemos"ta tartışmayı kazanmak için söz oyunları yapan kişilere eristik der ve diyalektikten ayırır.'),
  ('Xenophon\'un Sokrates\'i betimleyişi, Platon\'unkinden hangi bakımdan ayrışır?', 'Daha sade, pratik ahlak öğütleri veren bir kişi olarak', ['Metafizik kuramlar kuran ve idealar öğretisini işleyen bir filozof olarak', 'Matematik teoremleri öğreten bir hoca olarak', 'Askerî bir komutan olarak'], 'Xenophon\'un "Anılar"ında Sokrates gündelik, yararlı öğütlerle gösterilir. Platon ise onu idealar kuramı gibi daha derin düşüncelerle ilişkilendirir.'),
  ('Platon\'un "Menon" diyaloğundaki "Menon paradoksu" ne söyler?', 'Bilmediğimiz bir şeyi nasıl arayabiliriz, bulsak nasıl tanırız', ['Bilgi ile servet aynıdır', 'Erdem ölümle yok olur', 'Evrenin sonu yoktur'], 'Menon, bilinen şeyi aramaya gerek olmadığı, bilinmeyeni de arayamayacağımız için araştırmanın olanaksız olduğunu söyler. Sokrates anımsama kuramıyla yanıt verir.'),
  ('Platon\'un "Phaidon" diyaloğundaki "akrabalık argümanı"na göre ruh neye benzer?', 'Görünmez ve değişmeyen ideaya', ['Değişen ve görünen bedene, çürüyen', 'Ateşe', 'Rüzgâra'], 'Sokrates, ruhun görünmeyen, bileşik olmayan ve değişmeyen şeylere akraba olduğunu, bu yüzden bedenden farklı yaşayabileceğini söyler.'),
  ('Platon\'un "Politikos" diyaloğunda ideal yönetici neye benzetilir?', 'Dokumacı gibi toplumun farklı iplerini bir araya getiren bilge', ['Çoban gibi sürü yöneten silahlı', 'Demirci gibi', 'Denizci gibi'], 'Platon yönetimi bilgi gerektiren bir sanat sayar ve gerçek siyasetçiyi toplumu bir araya dokuyan dokumacıya benzetir.'),
  ('Aristarkhos\'un antik çağdaki bilimsel önemi nedir?', 'Güneş merkezli bir evren modelini ileri sürmesi', ['Atom kuramını kurması ve boşluğun varlığını kanıtlaması bakımından', 'Mantığı bulması', 'Teleskopu yapması'], 'Samoslu Aristarkhos MÖ 3. yüzyılda Dünya\'nın Güneş çevresinde döndüğünü savundu; ancak antik dünyada Aristoteles\'in Dünya merkezli modeli ağır bastı.'),
  ('Aristoteles\'in trajedi kuramında "hamartia" neyi anlatır?', 'Kahramanın bir yanılgı ya da hatayla felakete sürüklenmesini', ['Kahramanın tanrılara isyanını', 'Seyircinin sıkılmasını', 'Oyunun mutlu sonla bitmesini'], 'Hamartia, trajik kahramanın kötülük yüzünden değil bir yanılgı ya da muhakeme hatası yüzünden talihsizliğe düşmesidir.'),
  ('Aristoteles\'in "peripeteia" kavramı olay örgüsünde hangi dönüşü anlatır?', 'Olayların beklenenin tersi yönde ani dönüşünü', ['Kahramanın ölmesi ve oyunun trajik biçimde sona ermesi durumunu', 'Oyunun başlamasını', 'Korunun şarkı söylemesini'], 'Peripeteia, durumun kahraman için tersine dönmesi, anagnorisis ise bilgisizlikten bilgiye geçiş yani tanımadır.'),
  ('Aristoteles\'in yaptırdığı ve öğrencilerine hazırlattığı karşılaştırmalı siyasal çalışmanın içeriği nedir?', 'Yüz elliden fazla kentin anayasasının derlenmesi', ['Bir tiyatro oyunları derlemesi ve Atina\'daki gösteriler listesi', 'Yıldız haritaları', 'Matematik teoremleri'], 'Aristoteles ve öğrencileri 158 kentin anayasasını inceledi. Bunlardan günümüze ulaşan en önemlisi "Atinalıların Devleti"dir.'),
  ('Aristoteles\'in "dağıtıcı adalet" kavramı neyi anlatır?', 'Toplumsal değer ve ödüllerin, kişilerin değerine göre orantılı dağıtılmasını', ['Suçluların cezalandırılmasını', 'Eşit olmayan insanlara aynı payın verilmesini', 'Yargıçların seçilmesini'], 'Dağıtıcı adalet payların liyakate göre orantısal dağıtımıdır. Düzeltici adalet ise haksızlığın giderilmesiyle ilgilidir.'),
  ('Aristoteles\'in etiğinde "erdem" (aretê) nedir?', 'Seçme yeteneğine bağlı, akla uygun orta yolu bulan kalıcı huy', ['Doğuştan gelen değişmez özellik', 'Servet', 'Bilgi'], 'Aristoteles erdemi duyguları ve eylemleri aşırılık ile eksiklik arasında akılla belirlenen orta noktaya yönelten kalıcı bir huy sayar.'),
  ('Aristoteles\'e göre mutluluk için erdem yeterli midir?', 'Hayır; sağlık, dostlar ve ölçülü servet gibi dış iyiler de gereklidir', ['Evet; hiçbir dış koşul gerekmez', 'Hayır; yalnız servet yeterlidir', 'Mutluluk gerekli değildir'], 'Stoacılardan farklı olarak Aristoteles erdemli yaşamın yanında belirli dış iyilerin de mutlulukta rol oynadığını belirtir.'),
  ('Aristoteles\'e göre "gönüllü eylem"in koşulları nelerdir?', 'Failin eylemin kaynağı olması ve eylemin koşullarını bilmesi', ['Eylemin zorla yaptırılması', 'Eylemin bilgisizce yapılması', 'Eylemin tanrılarca belirlenmesi'], 'Gönüllü eylem, dışarıdan zorlanmamış ve ilgili koşullar bilinerek yapılan eylemdir; ahlaki sorumluluk bu eyleme bağlanır.'),
  ('Aristoteles\'in Metafizik\'inde "Varlık birçok anlamda söylenir" ifadesi neyi gösterir?', 'Varlığın töz, nitelik, nicelik gibi farklı kategorilerde anlam kazanması', ['Yalnız bir tür varlığın bulunması', 'Varlığın hiçbir anlamının olmaması', 'Varlığın yalnız sayı olması'], 'Aristoteles "varlık" teriminin tek anlamlı olmadığını, töz başta olmak üzere farklı kategorilere göre söylendiğini belirtir.'),
  ('Aristoteles çelişmezlik ilkesini inkâr eden kişi için ne söyler?', 'Böyle birinin anlamlı konuşmaktan kaçınması gerekir; bir bitki gibidir', ['Böyle biri haklıdır', 'Böyle birinin filozof olduğunu söyler', 'Böyle birini devlet yöneticisi yapar'], 'Aristoteles çelişmezliği reddeden kişiyle tartışmanın mümkün olmadığını, çünkü o kişinin anlamlı bir şey söyleyemeyeceğini belirtir.'),
  ('Aristoteles\'e göre zaman nedir?', 'Önce ve sonra bakımından hareketin sayısı', ['Mutlak boşluk, yani hareket etmeyen uzay genişliği', 'Bir tanrının adı', 'Atomların yok oluşu'], 'Aristoteles zamanı hareketten bağımsız bir şey olarak değil, harekette önceyi ve sonrayı sayarak ölçtüğümüz niceliği olarak tanımlar.'),
  ('Aristoteles\'in sonsuzluk anlayışında hangisi doğrudur?', 'Sonsuzluk potansiyel olarak vardır, aktüel olarak yoktur', ['Sonsuz büyüklükte aktüel bir cisim vardır ve evren sonsuzdur', 'Hiçbir biçimde sonsuzluk düşünülemez', 'Her şey aktüel sonsuzdur'], 'Aristoteles sonsuz bölünebilirlik ve zamanın sonsuzluğunu potansiyel anlamda kabul eder; gerçek bir sonsuz cismin bulunmasını reddeder.'),
  ('Aristoteles ağır cisimlerin hafif cisimlerden daha hızlı düştüğünü hangi gerekçeyle savunur?', 'Cismin ağırlığı arttıkça doğal yerine yönelişinin güçlenmesiyle', ['Havanın cisimleri itmesiyle', 'Tanrının iradesiyle', 'Gezegenlerin çekimiyle'], 'Aristoteles hızın ağırlıkla orantılı olduğunu düşündü; bu görüş Orta Çağ\'da Philoponus ve sonra Galileo tarafından eleştirildi.'),
  ('Aristoteles\'in hayvanları sınıflandırmasında ana ayrım hangisidir?', 'Kanlı (enaima) ve kansız (anaima) hayvanlar', ['Evcil hayvanlar ile yabani hayvanlar arasındaki ayrım ve yaşam alanı', 'Büyük ve küçük hayvanlar', 'Güzel ve çirkin hayvanlar'], 'Aristoteles hayvanları kan taşıyıp taşımamalarına göre ikiye ayırdı; bu ayrım yaklaşık olarak omurgalı-omurgasız ayrımına denk gelir.'),
  ('Aristoteles\'in biyolojik gözlemlerinde yunusla ilgili önemli saptaması nedir?', 'Yunusun balık değil, yavrusunu doğuran ve emziren bir memeli olduğunu fark etmesi', ['Yunusun balık olduğunu söylemesi', 'Yunusun böcek olduğunu söylemesi', 'Yunusun varlığını reddetmesi'], 'Aristoteles yunusun akciğerle solunum yaptığını ve canlı doğurduğunu gözleyerek onu balıklardan ayırdı.'),
  ('Aristoteles\'in "etkin akıl" (nous poietikos) hakkındaki görüşü nedir?', 'Etkin akıl ayrılabilir, ölümsüz ve ezelîdir', ['Etkin akıl ölümlüdür ve bedenle birlikte yok olur', 'Etkin akıl duyudan ibarettir', 'Etkin akıl yoktur'], 'Aristoteles ruh üzerine yazarken etkin aklı bedenden ayrı ve ölümsüz olarak betimler; bu pasaj yüzyıllar boyu yorumlanmıştır.'),
  ('Aristoteles\'e göre "bilim" (episteme) neye ilişkin bilgidir?', 'Zorunlu olanın nedenlerini bilmek', ['Değişen duyumlara ve görünüşlere dair bilgi, kişisel', 'Rastlantısal olaylar', 'Kişisel kanılar'], 'Bilim, genel ve zorunlu olanı nedenleriyle bilmektir; rastlantısal ve değişen şeyler bilimin konusu olamaz.'),
  ('Epikuros\'un bilgi kuramında doğru bilginin ölçütleri (kanon) arasında hangisi sayılır?', 'Duyumlar, önanlar (prolepsis) ve haz-acı duyguları', ['Yalnızca vahiy, yazılı kanun ve tanrıların buyruğu, deney dışında', 'Yalnız yazılı kanun', 'Yalnız tanrıların buyruğu'], 'Epikuros duyumların her zaman doğru olduğunu, yanılgının yargıdan kaynaklandığını söyler. Böylece duyu deneyimi bilgi için temel ölçüt olur.'),
  ('Lucretius\'un Epikuros\'tan aktardığı "Hiçbir şey yoktan var olmaz" ilkesi neyi destekler?', 'Maddenin yaratılmadığını ve yok olmayıp yalnızca biçim değiştirdiğini', ['Evrenin tanrılar tarafından yoktan yaratıldığını', 'Zamanın başlangıcı olduğunu', 'Ruhun beden dışında yaşadığını'], 'Atomcu görüşe göre madde yoktan çıkmaz ve yokluğa gitmez; doğadaki değişim atomların bir araya gelip ayrılmasıdır.'),
  ('Stoacılığın "oikeiosis" kavramı neyi anlatır?', 'Canlının önce kendini, sonra çevresini ve sonunda tüm insanlığı benimsemesini', ['Maddenin atomlara ayrılmasını', 'Ruhun göçünü', 'Kentin yıkılışını'], 'Oikeiosis, kendini koruma içgüdüsünden başlayarak yakınlık duygusunun aileye, topluma ve insanlığa genişlemesidir; Stoa etiğinin temellerinden biridir.'),
  ('Epiktetos\'un "Enkheiridion" (Elkitabı) nedir?', 'Öğrencisi Arrianos\'un derlediği, Stoacı öğütleri içeren kısa kılavuz', ['Epiktetos\'un devlet kuramı', 'Bir tiyatro oyunu', 'Bir tıp kitabı'], 'Elkitabı, Epiktetos\'un derslerinden seçilmiş ve günlük yaşamda uygulanacak Stoacı ilkeleri özetleyen kısa bir kitaptır.'),
  ('Seneca\'nın "Lucilius\'a Mektuplar"ı hangi alanda yazılmıştır?', 'Stoacı ahlak öğütleri ve yaşam felsefesi', ['Matematik ve geometri problemlerinin çözümü üzerine', 'Tıp', 'Askerî strateji'], 'Seneca, genç dostu Lucilius\'a gönderdiği mektuplarda ölüm, dostluk, zaman ve erdem gibi konuları ele alır.'),
  ('MÖ 155\'te Atina\'dan Roma\'ya gelen filozof elçilerin Roma\'daki felsefe tarihi açısından anlamı nedir?', 'Yunan felsefesinin Roma\'da ilgi görmesini sağlamış, Cato gibi muhafazakârlar tepki göstermiştir', ['Roma\'nın felsefeyi tümüyle benimsemesi', 'Roma\'da ilk üniversitenin kurulması', 'Felsefenin yasaklanması'], 'Karneades gibi filozofların konuşmaları Romalı gençleri etkiledi, Cato bu etkiden rahatsız olup elçilerin gönderilmesini istedi.'),
  ('Augustinus\'a göre Tanrı evreni nasıl yaratmıştır?', 'Evreni zamanın içinde değil, zamanla birlikte yaratmıştır', ['Evreni zamanın akışı içinde ve bir öncesi olan bir anda yaratmıştır', 'Evreni mevcut maddeden biçimlendirmiştir', 'Evreni hiç yaratmamıştır'], 'Augustinus "Zamanın yaratılmadan önce Tanrı ne yapıyordu?" sorusunu, zamanın evrenle birlikte yaratıldığını söyleyerek yanıtlar.'),
  ('Aquinas\'ın "Summa contra Gentiles" adlı eserinin amacı nedir?', 'Hristiyan öğretisini Hristiyan olmayan çevrelere akıl yoluyla savunmak', ['Yalnızca ayin kurallarını düzenlemek', 'Hukuk kitabı yazmak', 'Tıp bilgisi aktarmak'], 'Aquinas bu eseri Müslüman ve Yahudi bilginlerle tartışabilmek için vahye dayanmayan akıl yürütmeyi öne çıkararak yazdı.'),
  ('Aquinas\'a göre bilginin kaynağı konusundaki ünlü ilke hangisidir?', 'Zihinde, önce duyuda bulunmayan hiçbir şey yoktur', ['Bütün bilgi doğuştandır ve duyu deneyimi bilgiye hiçbir katkı yapmaz', 'Bilgi yalnız vahiyle gelir', 'Bilgi yalnız anımsamadır'], 'Aquinas Aristotelesçi biçimde bilginin duyu deneyimiyle başladığını, aklın duyu verilerinden soyutlama yaptığını söyler.'),
  ('Anselmus\'un "Cur Deus Homo" adlı eserinin konusu nedir?', 'Tanrı\'nın neden insan olduğu (enkarnasyon) sorusu', ['Tanrı\'nın varlığının akılla kanıtlanması ve kozmolojik kanıtın ayrıntıları', 'Yöntem kuralları', 'Kent yönetimi'], 'Canterbury Başpiskoposu Anselmus bu eserde Mesih\'in insan olmasının zorunluluğunu akılla açıklamaya çalışır.'),
  ('Clairvaux\'lu Bernard\'ın Abelard\'a yönelttiği eleştirinin özü nedir?', 'İnanç sırlarını akıl yürütmeye fazla tabi tuttuğu', ['Felsefe yapmadığı ve yalnızca kutsal metin yorumu ile uğraştığı için', 'İncil\'i okumadığı', 'Tarikat kurduğu'], 'Mistik Bernard, Abelard\'ın dinsel sırları mantıkla çözmeye çalışmasını tehlikeli buldu ve 1141 Sens Konsili\'nde mahkûmiyetini sağladı.'),
  ('13. yüzyıl başında Paris\'te Aristoteles\'in doğa felsefesi kitaplarına yönelik tutum nedir?', 'İlk önce yasaklandılar, sonra yüzyıl ortasında müfredata girdiler', ['Hemen müfredata alındılar ve ders kitabı oldular', 'Hiç tanınmadılar', 'Hiçbir zaman yasaklanmadılar'], '1210 ve 1215\'te Paris\'te Aristoteles\'in doğa felsefesi dersleri sınırlandı; 1255\'te ise Sanat Fakültesi programına Aristoteles\'in neredeyse bütün eserleri alındı.'),
  ('Rönesans hümanizminin antik düşünceye yaklaşımı skolastikten nasıl ayrılır?', 'Doğrudan Yunan ve Latin kaynaklara dönerek insanı merkeze alması', ['Antik düşünceyi tümüyle yasaklaması', 'Yalnız Arapça kaynaklara dayanması', 'Yalnız Kutsal Kitabı kullanması'], 'Hümanistler Orta Çağ şerhlerini aşıp orijinal metinlere gitmeyi hedefledi; insan ve dünyevi yaşam ilgi merkezine oturdu.'),
  ('Duns Scotus\'un "Subtle Doctor" (İnce Doktor) lakabı hangi özelliğine dayanır?', 'Çok ince mantıksal ayrımlar yapmasına', ['Çok kısa boylu olması ve küçük bir bedene sahip oluşu', 'Çok hızlı yazmasına', 'Çok az konuşmasına'], 'Scotus\'un ayrıntılı ve ince ayrımlarla dolu yazıları nedeniyle bu ad verilmiştir; ayrıca varlığın tekanlamlılığı gibi ayrımlarıyla da anılır.'),
  ('Razi\'nin hekimliğinde dikkat çeken yaklaşım hangisidir?', 'Hastaları gözleme ve vaka kayıtlarına dayalı klinik yöntem', ['Yalnızca büyü ve tılsıma, ayrıca hasta kaderine bağlı olarak', 'Yalnızca astroloji', 'Yalnızca eski kitapların tekrarı'], 'Razi hasta gözlemlerini kayıt altına alan, hastanelerde görev yapan, deney ve deneyime önem veren bir hekimdi.'),
  ('İslam mantığında "tasavvur" ile "tasdik" ayrımı neyi anlatır?', 'Tasavvur yalnızca kavram oluşturma, tasdik ise bir hüküm verme (doğru ya da yanlış kabul etme) işidir', ['İkisi aynı şeydir', 'Tasavvur yalnız vahiy, tasdik yalnız duyudur', 'Tasavvur hüküm, tasdik kavramdır'], 'Farabi ve İbn Sina\'dan gelen bu ayrımda tanım kavramla, kıyas ise hükümle ilgilidir.'),
  ('İbn Sina\'nın "Hayy b. Yakzan" adlı sembolik risalesinde ne anlatılır?', 'Ruhun akıl rehberiyle bilgelik yolculuğunu', ['Bir savaş günlüğünün anlatımı ve komutanın seferleri', 'Matematik soruları', 'Tıp reçeteleri'], 'İbn Sina\'nın bu mistik-felsefi hikâyesinde bir bilge, ruhun yolculuğunu simgeler. İbn Tufeyl\'in aynı adlı romanından farklıdır.'),
  ('İbn Rüşd\'e göre toplumdaki insanlar hakikati kavrayış düzeylerine göre kaç ikna yoluyla ele alınır?', 'Hitabi, cedeli ve burhani olmak üzere üç yolla', ['Yalnız bir yolla, yani hitabetle her zaman ikna edilir', 'Beş yolla', 'Yedi yolla'], 'İbn Rüşd, halkın hitabet yoluyla, kelamcıların cedel (tartışma) yoluyla, filozofların ise kesin kanıt (burhan) yoluyla ikna olduğunu söyler.'),
  ('Latin Batı\'da İbn Rüşd\'ün Aristoteles şerhlerinin etkisi nasıl özetlenebilir?', 'Aristoteles\'in standart yorumcusu olarak "Şarih" diye anılmış ve skolastik tartışmalarda belirleyici olmuştur', ['Hiç bilinmemiştir', 'Yasaklanıp hiç okunmamıştır', 'Yalnızca şiir olarak okunmuştur'], 'Aquinas gibi düşünürler İbn Rüşd\'ü hem kaynak hem karşı görüş olarak kullandı; "Aristoteles filozoftur, İbn Rüşd şarihtir" sözü ünlüdür.'),
  ('İslam düşüncesinde "hikmet" terimi çoğunlukla hangi alana karşılık gelir?', 'Felsefe ve bilgelik', ['Yalnız ticaret ve alışveriş bilgisi', 'Yalnız askerlik', 'Yalnız dil bilgisi'], 'Hikmet, İslam düşüncesinde Yunan kökenli felsefeyi ve bilgelik arayışını anlatır; filozofa "hakim" denir.'),
  ('Kelam ilminin temel görevi nedir?', 'İslam inanç esaslarını akılla temellendirip savunmak', ['Hekimlik yapmak ve hastalıkların nedenlerini deneyle araştırmak', 'Şiir yazmak', 'Yıldızları gözlemek'], 'Kelam, dinî inanç konularını akıl ve delille açıklayıp karşı görüşlere yanıt verme çabasıdır; "söz" anlamına gelir.'),
  ('Mâtürîdî\'nin "Kitâbü\'t-Tevhid"i hangi ekolün temel metinlerindendir?', 'Mâtürîdîliğin', ['Mutezile\'nin görüş kitabı olarak', 'Cebriye\'nin', 'Kaderiye\'nin'], 'Mâtürîdî\'nin Tevhid kitabı, Sünnî kelamın iki büyük çizgisinden biri olan Mâtürîdî düşüncenin başlıca kaynağıdır.'),
  ('İbn Arabi\'nin hayatının son yıllarını geçirdiği ve öldüğü şehir hangisidir?', 'Şam', ['Kordoba', 'Toledo', 'Granada'], 'İbn Arabi Mürsiye\'de doğdu, Sevilla\'da öğrenim gördü, doğuya göç edip Mekke, Anadolu ve en sonunda Şam\'da yaşadı ve orada öldü.'),
  ('Sadreddin Konevi\'nin İbn Arabi ile ilişkisi nedir?', 'İbn Arabi\'nin öğrencisi ve düşüncesinin Anadolu\'daki başlıca yorumcusu olması', ['İbn Arabi\'nin rakibi olması', 'İbn Arabi\'yi hiç tanımaması', 'İbn Arabi\'ye şiir yazması'], 'Konya\'da yaşayan Konevi, İbn Arabi\'nin yetiştirdiği bir bilgindi; Mevlana ile de çağdaştı ve tasavvuf düşüncesini sistemleştirdi.'),
  ('Aşağıdaki ilke-filozof eşleştirmelerinden hangisi yanlıştır?', 'Herakleitos – hava', ['Thales – su', 'Anaksimandros – apeiron', 'Pythagoras – sayı'], 'Arkhe olarak su Thales, apeiron Anaksimandros, hava Anaksimenes, ateş Herakleitos, sayı Pythagorasçılarla anılır.'),
  ('Aquinas\'ın evrenseller konusundaki ılımlı gerçekçiliği neyi söyler?', 'Evrenseller nesnelerde form olarak vardır ve zihin onları soyutlar', ['Evrenseller yalnızca sözcüklerdir', 'Evrenseller bireylerden önce bağımsız varlıklardır', 'Evrenseller yoktur'], 'Aquinas, Aristotelesçi biçimde türlerin nesnelerin içindeki formlar olarak bulunduğunu ve zihnin bunları soyutlayarak evrensel kavramlar oluşturduğunu söyler.'),
  ('Şiirin dönemlerine göre "Hesiodos\'un Theogonia\'sı" bir mit anlatımıdır. Bu metni felsefi metinlerden ayıran en temel özellik nedir?', 'Olayların kaynağını tanrısal kişilerin eylemlerine dayandırması', ['Doğa nedenlerini araştırması', 'Akıl yürütmeye başvurması', 'Kanıtlar sunması'], 'Theogonia tanrıların soyağacını anlatır; felsefi açıklama ise doğadaki nedenleri akılla araştırır.'),
  ('Epikuros ve Stoa\'nın ortak yönü aşağıdakilerden hangisidir?', 'Mutluluğu ruhsal dinginlik ve kaygıdan kurtulmaya bağlamaları', ['Evreni tanrıların yönettiğini söylemeleri', 'Duygu ve arzuları yüceltmeleri', 'Siyasete katılmayı zorunlu saymaları'], 'Her iki okul da felsefeyi yaşam sanatı olarak görür ve ruhun huzurunu amaçlar. Aralarındaki fark kaygıdan kurtuluşun yoludur.'),
  ('Augustinus\'un ve Aquinas\'ın Aristoteles ile ilişkileri nasıl ayrışır?', 'Augustinus Platoncu, Aquinas Aristotelesçi bir temele yaslanır', ['Augustinus Aristotelesçi, Aquinas Platoncudur', 'İkisi de Epikurosçudur', 'İkisi de felsefeyi reddeder'], 'Augustinus Yeni Platoncu etkiyle ruha ve iç aydınlanmaya, Aquinas ise Aristotelesçi biçimde duyu deneyimine dayanan bilgiye ağırlık verir.'),
  ('Hippokrates\'in "kutsal hastalık" (sar\'a) hakkındaki görüşü nedir?', 'Hastalığın tanrısal değil, doğal nedenleri olduğunu savunur', ['Hastalığın tanrıların cezası olduğunu ve yalnız dualarla geçebileceğini', 'Hastalığın yalnız büyüyle iyileşeceğini söyler', 'Hastalığın yoktur diye reddeder'], 'Hippokratesçi metin sar\'a hastalığının diğerleri gibi doğal nedenlerinin bulunduğunu, tanrısal bir müdahale olmadığını söyler.'),
  ('Perikles dönemi Atina\'sında Sofistlerin rağbet görmesinin nedeni nedir?', 'Demokraside halk meclisinde ikna edici konuşma yeteneğine duyulan gereksinim', ['Rahip sınıfının sofist yetiştirmesi', 'Şehirlerin savaşlardan uzak durması', 'Felsefenin yasaklanması'], 'Atina demokrasisinde siyasal başarı için retorik beceri önemliydi; sofistler ücret karşılığı bu becerileri öğretiyordu.'),
  ('Hellenistik dönemde felsefenin bireysel huzuru önemseyen yönelimlere kayması hangi gelişmeyle ilişkilendirilir?', 'Kent-devletlerin bağımsızlığını yitirip büyük krallıklara bağlanması', ['Matbaanın icadı', 'Haçlı Seferleri', 'Yazının bulunması'], 'Atina\'nın İskender sonrası siyasal gücünü kaybetmesi, bireyi kamusal alandan çekip iç huzurunu aramaya yöneltti.'),
  ('İskenderiye\'deki Mouseion (Müze) ve Kütüphane hangi hanedan döneminde kurulmuştur?', 'Ptolemaios hanedanı', ['Selevkos hanedanı', 'Antigonos hanedanı', 'Pers Ahameniş hanedanı'], 'Ptolemaios yöneticileri İskenderiye\'yi bilim ve bilgi merkezi yapmak için Mouseion\'a bilginleri topladı.'),
  ('Ptolemaios\'un "Almagest" adlı eseri neyi sunar?', 'Dünya merkezli gezegen hareketleri modelini', ['Güneş merkezli bir gezegen sistemini ve yıldızların hareketini', 'Atom kuramını', 'Kıyas kuramını'], 'Ptolemaios\'un matematiksel astronomisi, Kopernik\'e kadar Avrupa ve İslam dünyasında standart gök modeli olarak kullanıldı.'),
  ('Aphrodisias\'lı Aleksandros\'un Aristoteles felsefesi tarihindeki yeri nedir?', 'Aristoteles\'in antik çağdaki en önemli şarihi olarak anılması', ['Epikurosçuluğun kurucusu olması', 'Hristiyan apologisti olması', 'Skolastik bir filozof olması'], 'MS 2.-3. yüzyılda yaşayan Aleksandros, Aristoteles\'in eserlerine yaptığı yorumlarla tanındı ve sonraki Arap ve Latin yorumcuları etkiledi.'),
  ('"Felsefe teolojinin hizmetçisidir" (philosophia ancilla theologiae) sözü Orta Çağ\'da neyi anlatır?', 'Felsefenin dinî öğretiye hizmet etmesi gerektiği anlayışını', ['Felsefenin teolojiden bağımsız olduğunu', 'Felsefenin yasak olduğunu', 'Teolojinin gereksiz olduğunu'], 'Bu görüş, mantık ve felsefenin inancı savunmak ve açıklamak için kullanılması gerektiğini savunur; Petrus Damiani ile özdeşleştirilir.'),
  ('Çin\'de Neo-Konfüçyüsçülüğün (Lixue) en etkili sistemcisi olarak bilinen 12. yüzyıl filozofu kimdir?', 'Zhu Xi', ['Mozi', 'Han Fei', 'Zhuangzi'], 'Zhu Xi, Konfüçyüsçü gelenek ile Daoculuk ve Budizm\'in metafizik unsurlarını bütünleştiren bir sistem kurdu ve Çin eğitim sistemini yüzyıllarca belirledi.'),
  ('"Dao De Jing" adı hangi anlamlara sahip kavramlardan oluşur?', 'Yol (dao), erdem ya da güç (de), kitap', ['Gök, yer ve insan olmak üzere üç kavramdan oluşan ad', 'Su, ateş, hava', 'Yasa, ceza, ödül'], 'Dao De Jing\'in adı "Yol ve Erdem Kitabı" biçiminde çevrilir; Lao Zi\'ye atfedilir.'),
  ('Hindistan\'da Budizm\'in yayılmasında hangi hükümdarın rolü büyüktür?', 'Ashoka (Eşoka)', ['İskender (Makedonyalı kral)', 'Akbar', 'Chandragupta'], 'MÖ 3. yüzyılda Maurya hükümdarı Ashoka, Budizm\'i benimsedi ve elçiler göndererek Hindistan dışına yayılmasını sağladı.'),
  ('Budizmin Mahayana kolunun ayırt edici özelliği nedir?', 'Bodhisattva ideali: başkalarının kurtuluşu için kendi nirvanasını erteleme', ['Yalnız manastır yaşamını önemseme', 'Tanrı\'ya tapınmayı yasaklama', 'Yalnız Pali kutsal metinlerini kabul etme'], 'Mahayana ("büyük araç"), tüm canlıların kurtuluşunu hedefleyen merhamet ve bodhisattva ideali üzerine kuruludur; Theravada ise bireysel kurtuluşu vurgular.'),
  ('Jainizm\'in kurucusu olarak anılan Mahavira\'nın öğretisinde temel ilke nedir?', 'Ahimsa ve zorlu çilecilikle ruhun arınması', ['Tanrı\'ya tapınma ve ayinlerle kurtuluş ritüeli', 'Yalnız servet birikimi', 'Savaş yoluyla kurtuluş'], 'Mahavira, MÖ 6. yüzyılda yaşayan ve Buda\'ya çağdaş olduğu söylenen bir öğretmendir; ruhun bedenin ve karmanın bağından arınması gerektiğini öğretir.'),
  ('Patanjali\'nin "Yoga Sutraları"nda yoga neyi hedefler?', 'Zihnin dalgalanmalarının durdurulması', ['Bedensel güç kazanma ve cisimleri hareket ettirme gücü', 'Savaş becerisi', 'Tanrılara kurban sunma'], 'Yoga Sutraları yoganın tanımını zihnin dalgalanmalarının durması olarak verir; sekiz basamaklı bir uygulama yolu sunar.'),
  ('Hint felsefesinde Nyaya okulunun özgün katkısı nedir?', 'Doğru bilgi araçlarını (algı, çıkarım, benzetme, tanıklık) sistemleştiren mantık ve bilgi kuramı', ['Atomculuk', 'Nirvana öğretisi', 'Sanat kuramı'], 'Nyaya, geçerli bilgi kaynaklarını (pramana) inceleyen ve tartışma kuralları geliştiren mantık geleneğidir.'),
  ('Hint felsefesinde Vaisheshika okulu hangi görüşle tanınır?', 'Evrenin bölünmez atomlardan (paramanu) oluştuğu görüşüyle', ['Her şeyin boşluktan ibaret olduğu ve atomların bulunmadığı görüşüyle', 'Her şeyin ruhtan ibaret olduğu görüşüyle', 'Hiçbir şeyin var olmadığı görüşüyle'], 'Vaisheshika maddeyi dört temel öğenin atomlarına ayırır ve kategori sistemi geliştirir; Yunan atomculuğuyla karşılaştırılır.'),
  ('Kaşgarlı Mahmud\'un "Divanü Lügati\'t-Türk" adlı eserinin önemi nedir?', 'Türk dilleri ve kültürü üzerine ilk kapsamlı sözlük olması', ['Bir felsefe sistemi kurması ve mantık kuralları öğretmesi', 'Bir mantık kitabı olması', 'Bir tıp ansiklopedisi olması'], '11. yüzyılda Arapça yazılan eser, Türkçe sözcükleri örneklerle ve atasözleri, şiirlerle birlikte kaydeder.'),
  ('Orta Çağ Avrupası\'nda "Engizisyon" kurumunun felsefe düşüncesine etkisi nasıl değerlendirilir?', 'Dinsel öğretiye aykırı görülen düşüncelerin sorgulanmasına yol açarak düşünce özgürlüğünü kısıtlamıştır', ['Felsefenin gelişmesini teşvik etmiştir', 'Bilimsel deneyleri başlatmıştır', 'Üniversiteleri kurmuştur'], 'Kilisenin sapkınlık olarak gördüğü görüşleri yargılaması, bazı düşünürlerin yazılarının kınanmasına neden oldu.'),
  ('Aristoteles\'in Metafizik\'indeki "birinci felsefe" (prote philosophia) aynı zamanda hangi alanı da ima eder?', 'İlahiyat (teoloji): ilk hareket ettirici', ['Matematik ve sayıların doğası üzerine araştırma', 'Biyoloji', 'Poetika'], 'Aristoteles birinci felsefeyi varlığın en yüksek ilkelerini ve ilahi töz konusunu inceleyen bilim olarak da tanımlar.'),
  ('Antik Yunan\'da "Orfik gelenek"in ruh anlayışı hangi felsefeyi etkilemiştir?', 'Pythagorasçılığı ve Platon\'un ruh göçü düşüncesini', ['Epikurosçuluğu ve atomcu doğa görüşünü, ruhun ölümlü olduğunu', 'Atomculuğu', 'Sofistiği'], 'Orfik topluluklar ruhun ölümsüzlüğüne ve bedene hapsolduğuna inanıyordu; bu inanç Pythagorasçılar ve Platon\'un Phaidon\'unda yankılanır.'),
  ('Platon\'un "Devlet"inin sonunda anlatılan "Er mitosu" neyi anlatır?', 'Ölümden sonra ruhların yargılanıp yeni yaşamlarını seçmelerini', ['Atlantis\'in batışını', 'Troya Savaşı\'nı', 'Evrenin yaratılışını'], 'Savaşta ölen Er, ölümden sonra gördüklerini anlatır: ruhlar ödül ve ceza aldıktan sonra yeni bir yaşam seçer. Bu mit adaletin sonsuz karşılığını vurgular.'),
  ('Platon\'a göre bireyde adalet nasıl gerçekleşir?', 'Ruhun akıl, irade ve arzu parçalarının, aklın önderliğinde uyum içinde çalışmasıyla', ['Yalnız arzuların egemenliğiyle', 'Yalnız iradenin egemenliğiyle', 'Yasalara körü körüne uymakla'], 'Platon devlet ile ruh arasında benzerlik kurar: devlette sınıflar uyumlu çalışınca adalet vardır; bireyde de ruhun üç parçası uyum içindeyse adalet gerçekleşir.'),
  ('Aristoteles\'in ekonomi anlayışında para kazanma sanatının (khrematistike) bir uç biçimi olarak eleştirdiği şey nedir?', 'Faiz ve paranın para doğurması', ['Tarım, toprak işlemek ve ürün almak', 'Zanaat', 'Takas'], 'Aristoteles parayı değişim aracı olarak meşru, ama ondan para kazanmayı amaçlayan faizciliği doğaya aykırı sayar. Bu görüş Orta Çağ iktisat düşüncesini etkiledi.'),
  ('Aristoteles\'in "Fizik"inde doğa (physis) nasıl tanımlanır?', 'Kendi içinde hareket ve duruş ilkesi bulunan şeylerin ilkesi', ['Yalnızca insan yapımı nesneler', 'Yalnızca gökyüzü', 'Yalnızca tanrıların iradesi'], 'Aristoteles\'e göre doğal şeylerde hareketin kaynağı kendi içlerindedir; yapay şeylerde ise dışarıdan gelir. Bu ayrım doğa ve sanat arasında önemlidir.'),
  ('Aristoteles\'in bilimleri sınıflandırmasında "teorik bilimler" arasında hangisi yer alır?', 'Fizik, matematik ve birinci felsefe', ['Etik, politika ve devlet yönetimi bilimleri, yani pratik bilimler', 'Poetika ve retorik', 'Tarım ve ticaret'], 'Aristoteles bilimleri teorik, pratik ve yaratıcı (poietik) olarak üçe ayırır: teorik olanlar bilgi için, pratik olanlar eylem için, poietik olanlar üretim içindir.'),
  ('Aristoteles\'e göre felsefenin doğabilmesi için gerekli olan koşul nedir?', 'Boş zaman (skholē) ve ihtiyaçların karşılanmış olması', ['Savaş ve ordunun eğitimi, askerî disiplinin yerleşmesi koşulu', 'Yoksulluk', 'Din baskısı'], 'Aristoteles "Metafizik"te felsefe yapmanın, gündelik zorunlulukları karşılandıktan sonra boş zaman bulan toplumlarda başladığını söyler.'),
  ('Kleanthes\'in "Zeus İlahisi"nde işlenen düşünce nedir?', 'Evrenin Zeus (logos) tarafından yönetildiği ve akıllı insanın bu düzenle uyum içinde yaşaması gerektiği', ['Zeus\'un öldüğü', 'Tanrıların savaştığı', 'Evrenin rastlantıyla oluştuğu'], 'Stoa\'nın ikinci başkanı Kleanthes, ilahisinde Zeus\'u doğa yasasını yöneten akıl olarak över.'),
  ('Boethius\'un "kişi" (persona) tanımı nedir?', 'Akıl sahibi bireysel doğanın tözü', ['Bir tiyatro oyuncusunun taktığı maske veya rolü', 'Bir toplumsal rol', 'Bir yasal kimlik'], 'Boethius, kişiyi "akıl sahibi bireysel bir doğanın tözü" diye tanımladı; bu tanım sonraki Orta Çağ felsefesi ve teolojisini etkiledi.'),
  ('Eriugena\'nın Orta Çağ Latin dünyasındaki çeviri katkısı nedir?', 'Pseudo-Dionysios\'un Yunanca yazılarını Latinceye çevirmesi', ['Aristoteles\'in Fizik\'ini Latinceye çevirmesi ve skolastik yöntemi başlatması', 'İbn Sina\'yı çevirmesi', 'Kuran\'ı çevirmesi'], '9. yüzyılda Eriugena\'nın çevirileri, Yeni Platoncu Hristiyan mistik geleneği Batı\'ya taşıdı.'),
  ('Roger Bacon\'un "dört engel" olarak saydığı hakikate ulaşmayı güçleştiren etkenler hangi seçenekte doğru verilmiştir?', 'Güvenilmez otorite, gelenek, halk kanısı ve bilgiçlik taslama', ['Zenginlik, güç, ün, haz', 'Savaş, kıtlık, hastalık, ölüm', 'Dil, yazı, sayı, ses'], 'Bacon, "Opus Majus"ta otoriteye körü körüne güvenme, gelenek, kalabalığın görüşü ve bilgisizliği gizleme eğilimini hakikate engel olarak sıralar.'),
  ('Aristoteles\'in doğa anlayışında dört öğe ile nitelikler arasındaki ilişki nasıldır?', 'Ateş sıcak-kuru, hava sıcak-ıslak, su soğuk-ıslak, toprak soğuk-kuru niteliktedir', ['Her öğe yalnız bir niteliğe sahiptir', 'Öğelerin nitelikleri yoktur', 'Öğeler sayılardan oluşur'], 'Aristoteles dört öğeyi sıcak, soğuk, ıslak ve kuru niteliklerin ikili birleşmeleriyle açıklar; böylece öğeler birbirine dönüşebilir.'),
  ('İslam felsefesinde "âlemin kıdemi (ezelîliği)" tartışması en çok hangi eserlerle öne çıkar?', 'Gazali\'nin Tehafüt\'ü ve İbn Rüşd\'ün Tehafütü\'t-Tehafüt\'ü', ['İbn Haldun\'un Mukaddime\'si ve Tarih adlı kitabında toplum', 'Farabi\'nin İhsaü\'l-Ulum\'u', 'Kindi\'nin Optik kitabı'], 'Filozoflar evrenin ezelî olduğunu savunmuş, Gazali bunu tekfir sebebi sayarak eleştirmiş, İbn Rüşd bu eleştiriyi yanıtlamıştır.'),
  ('Orta Çağ Latin Batı\'da "otorite" (auctoritas) kavramı neyi anlatır?', 'Kutsal Kitap, kilise babaları ve Aristoteles gibi saygın kaynakların kanıt değeri', ['Kralın yetkisi', 'Üniversite rektörlüğü', 'Askerî komutanlık'], 'Skolastik tartışmada otorite alıntıları kanıt sayılırdı; ama Abelard gibi düşünürler çelişen otoriteleri akılla uzlaştırmaya çalıştı.'),
  ('Hristiyan düşüncesinde "Teslis" (Üçleme) öğretisinin felsefi biçimlenişinde hangi kavramlar öne çıkmıştır?', 'Töz (ousia) ve kişi (hypostasis, persona) kavramları', ['Atom ve boşluk kavramları ile hareketin yanılsama olduğu görüşü', 'Madde ve form', 'Sayı ve oran'], 'Kapadokya Babaları ve Latin yazarlar, tek bir tözün üç kişide bulunduğunu açıklamak için Yunan felsefesinin terimlerini kullandı.'),
  ('Porphyrios\'un "Plotinos\'un Hayatı" adlı yazısı felsefe tarihi açısından neden değerlidir?', 'Plotinos\'un yaşam ve öğretisine ilişkin ana kaynak olması', ['Aristoteles\'in yaşamını anlatan ve kitaplarını listeleyen bir biyografi olması', 'Sokrates\'in idamını anlatması', 'Pythagoras\'ın yaşamını anlatması'], 'Porphyrios, hocasını yakından tanıyan bir öğrenci olarak Plotinos\'un yaşamı ve çalışma biçimi hakkında bilgi verir ve Enneadlar\'ı düzenler.'),
  ('Orta Çağ\'da bir şeyin "mümkün" olması ile "zorunlu" olması arasındaki ayrım hangi düşünürde Tanrı kanıtına temel olmuştur?', 'İbn Sina', ['Ockham', 'Roscelinus', 'Eriugena'], 'İbn Sina mümkün varlıkların kendi başlarına var olamayıp zorunlu varlığa bağlı olduğunu savundu. Aquinas\'ın üçüncü yolu bu düşünceye yakındır.'),
  ('Platon\'un bilgi kuramında "sanı" ile "bilgi" ayrımının siyasal sonucu nedir?', 'Yönetimin bilgiye sahip filozoflara bırakılması gerektiği', ['Yönetimin halka bırakılması gerektiği ve herkesin eşit oy kullanması', 'Yönetimin zenginlere bırakılması', 'Yönetimin askerlere bırakılması'], 'Platon, çoğunluğun yalnızca sanıya sahip olduğunu, gerçek bilgiye ise filozofların eriştiğini söyler. Bu yüzden yöneticilerin filozof olmasını ister.'),
  ('Aristoteles\'in, İskender\'in ölümünden sonra Atina\'dan ayrılırken söylediği aktarılan söz neyle ilgilidir?', 'Atinalıların felsefeye karşı ikinci kez suç işlemesini istemediği', ['Atina\'nın yıkılacağını', 'Makedonya\'nın düşeceğini', 'Lykeion\'un kapatılacağını'], 'Sokrates\'in idamını anan bu söz, Makedon karşıtı bir ortamda yargılanma tehdidinden kaçınmayı anlatır. Aristoteles Khalkis\'e gitti.'),
  ('Aristoteles\'in öğrencisi Theophrastos\'un "Karakterler" adlı eseri neyi yapar?', 'İnsan tiplerini kısa ve canlı karakter betimlemeleriyle anlatır', ['Matematiksel ispatlar sunar', 'Tanrı kanıtları ileri sürer', 'Devlet kuramı yazar'], 'Theophrastos, cimri, laf ebesi, kibirli gibi otuz karakter tipini betimleyerek ahlaki gözleme dayalı bir eser verdi.'),
  ('Plotinos\'un Roma\'daki okulu ile ilişkilendirilen imparator kimdir?', 'Gallienus', ['Konstantin', 'Justinianus', 'Marcus Aurelius'], 'Plotinos Roma\'da öğretmenlik yaptı; İmparator Gallienus ve eşinin desteğiyle Campania\'da filozoflara özgü "Platonopolis" kurma planı yaptığı anlatılır.'),
  ('İbn Sina\'nın Hamedan\'daki siyasal görevi nedir?', 'Emir Şemsüddevle\'nin veziri olarak çalışması', ['Papalık elçisi olarak Roma\'ya gönderilip kiliseyle anlaşma yapması', 'Rasathane yöneticisi', 'Hâkim olarak görev yapması'], 'İbn Sina siyasal çalkantılar nedeniyle Buhara\'yı terk ettikten sonra Hamedan\'da emire hekim ve vezir olarak hizmet etti.'),
  ('Platon\'un "Protagoras" diyaloğunda tartışılan temel konu nedir?', 'Erdemin öğretilip öğretilemeyeceği ve erdemlerin birliği', ['Evrenin yaratılışı ve zamanın başlangıcı üzerine görüşler', 'Ruhun ölümsüzlüğü', 'Siyasi sınıflar'], 'Sofist Protagoras ile Sokrates\'in tartışmasında, erdem öğretilebilir mi ve çeşitli erdemler tek bir bilgi mi sorusu ele alınır.'),
  ('Platon\'un "Hippias Minör" diyaloğundaki ilginç savı nedir?', 'Bile bile yanlış yapan, yanılarak yanlış yapandan daha iyi olabilir', ['Her yalanın kötü olduğu', 'Her bilginin doğuştan olduğu', 'Her şairin bilge olduğu'], 'Sokrates bu diyalogda erdem bir beceri ise bilerek hata yapmanın beceri gerektirdiğini söyleyerek çarpıcı bir paradoksa varır.'),
  ('Platon\'un "Kratylos" diyaloğunda tartışılan sorun nedir?', 'Adların doğa gereği mi yoksa anlaşmayla mı doğru olduğu', ['Devlet yönetimi ve en iyi yönetim biçiminin hangisi olduğu sorunu', 'Erdem öğretimi', 'Ruhun ölümsüzlüğü'], 'Kratylos\'ta dil felsefesi sorunu tartışılır: adlar şeylerin doğasını mı yansıtır, yoksa uzlaşıma mı dayanır?'),
  ('Aristoteles\'in "Nikomakhos\'a Etik" adının kökeni nedir?', 'Oğlu veya babası Nikomakhos\'la ilişkilendirilmesi', ['Aristoteles\'in doğduğu kentin adı ve oradaki bir tapınağın ismi', 'Bir savaşın adı', 'Bir tanrının adı'], 'Eserin adı Aristoteles\'in oğlu (ya da babası) Nikomakhos\'la ilişkilendirilir; ders notlarını bir araya getiren editör olabilir.'),
  ('Aristoteles\'in "Eudemos\'a Etik" ile "Nikomakhos\'a Etik" arasındaki ilişki nasıl nitelenir?', 'İki ayrı ama benzer etik yapıt olup ortak kitapları bulunur', ['Biri etik, öbürü fizik kitabıdır', 'Biri Platon\'a aittir', 'İkisi aynı kitaptır'], 'Aristoteles\'e atfedilen iki ayrı etik yapıttır; üç kitap (adalet, erdem, haz-dostluk bölümleri) her ikisinde ortak sayılır.'),
  ('Lykeion\'un halefi Straton\'un felsefe tarihindeki ünü nedir?', 'Doğa felsefesine ağırlık vermesi nedeniyle "fizikçi" diye anılması', ['Matematik bilginliği', 'Retorik üstadlığı', 'Ahlak öğretmenliği'], 'Theophrastos\'tan sonra okulun başına geçen Straton, doğa olaylarını mekanik nedenlerle açıklamaya yönelik olduğu için "Fizikçi" lakabıyla anılır.'),
  ('Platon\'un öğrencisi Eudoxos\'un, Aristoteles\'in kozmolojisine zemin hazırlayan katkısı nedir?', 'Gök cisimlerinin iç içe küreler hareketiyle açıklanması', ['Atom kuramı ve evrenin yalnızca atom hareketinden oluştuğu görüşü', 'Kıyas kuramı', 'Etik kuramı'], 'Akademia\'da çalışan Eudoxos\'un küre modeli, Aristoteles\'in kozmolojisinin başlangıç noktalarından biriydi.'),
  ('Pythagorasçılığın "sayı" anlayışında "1" neyi simgeler?', 'Tek, bölünmez ve her şeyin kaynağı olan birlik', ['Çokluk, yani bölünebilen ve sayılabilen kalabalık', 'Boşluk', 'Zıtlık'], 'Pythagorasçılar birliği (monas) bütün sayıların kaynağı sayar; çift ve tek sayıları sınırsız ve sınırlı ilkeleriyle ilişkilendirir.'),
];
